INSERT INTO `lessons` (`id`, `title_ru`, `slug`, `lesson_order`, `content`, `is_published`) VALUES
(5, 'Знакомство с Linux', 'linux-intro', 1, '{\"theory\":\"<p><strong>Что такое Linux<\\/strong><\\/p><p>Linux — это операционная система. Она управляет всеми ресурсами компьютера: процессором, оперативной памятью, дисками, сетью и устройствами.<\\/p><p>Строго говоря, Linux — это только ядро операционной системы. Именно ядро взаимодействует с оборудованием компьютера. Но в повседневной жизни словом «Linux» обычно называют всю операционную систему целиком.<\\/p><p>Существует огромное количество готовых операционных систем на базе Linux. Они называются дистрибутивами.<\\/p><p>Наиболее известные дистрибутивы:<\\/p><p>Ubuntu, Debian, Fedora, Arch Linux<\\/p><p>В данном курсе используется Ubuntu Linux, поскольку именно она установлена в GitHub Codespaces.<\\/p><p>&nbsp;<\\/p><p><strong>Где используется Linux<\\/strong><\\/p><p>Сегодня Linux используется практически во всех направлениях информационных технологий.<\\/p><p>- Веб-серверы<\\/p><p>- Облачные платформы<\\/p><p>- Дата-центры<\\/p><p>- Суперкомпьютеры<\\/p><p>- Маршрутизаторы и сетевое оборудование<\\/p><p>- Android-смартфоны<\\/p><p>- Встраиваемые устройства<\\/p><p>- Контейнеры Docker<\\/p><p>- Платформы Kubernetes<\\/p><p>Большинство сайтов, которыми люди пользуются каждый день, работают именно под управлением Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Чем Linux отличается от других операционных систем<\\/strong><\\/p><p>Основные особенности Linux:<\\/p><p>- Свободное распространение.<\\/p><p>- Открытый исходный код.<\\/p><p>- Высокая стабильность.<\\/p><p>- Высокая безопасность.<\\/p><p>- Большое количество бесплатных программ.<\\/p><p>- Удобство автоматизации с помощью терминала.<\\/p><p>- Работа практически на любом оборудовании.<\\/p><p>В отличие от Windows, Linux изначально создавался как многопользовательская и многозадачная система.<\\/p><p>По сравнению с macOS Linux предоставляет пользователю значительно больше возможностей по настройке системы.<\\/p><p>&nbsp;<\\/p><p><strong>Место Linux в мире IT<\\/strong><\\/p><p>Практически каждый специалист в современной IT сталкивается с Linux.<\\/p><p>Его используют:<\\/p><p>- системные администраторы;<\\/p><p>- DevOps-инженеры;<\\/p><p>- Backend-разработчики;<\\/p><p>- специалисты по информационной безопасности;<\\/p><p>- инженеры облачных платформ;<\\/p><p>- администраторы баз данных;<\\/p><p>- специалисты по искусственному интеллекту.<\\/p><p>Даже если разработка ведётся на компьютере с Windows или macOS, очень часто конечное приложение работает именно на сервере под управлением Linux.<\\/p><p>Поэтому знание Linux сегодня является одним из базовых навыков любого IT-специалиста.<\\/p><p>&nbsp;<\\/p><p><strong>Краткое устройство Linux<\\/strong><\\/p><p>Любую систему Linux можно представить в виде нескольких уровней.<\\/p><p>- Пользователь.<\\/p><p>- Программы.<\\/p><p>- Командная оболочка (Shell).<\\/p><p>- Ядро Linux.<\\/p><p>- Аппаратное обеспечение.<\\/p><p>Ядро управляет оборудованием.<\\/p><p>Командная оболочка передаёт команды пользователя ядру.<\\/p><p>Программы используют возможности операционной системы через ядро.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое терминал<\\/strong><\\/p><p>Терминал — это программа, позволяющая работать с операционной системой при помощи текстовых команд.<\\/p><p>Вместо нажатия кнопок мышью пользователь вводит команды с клавиатуры.<\\/p><p>Именно через терминал чаще всего работают:<\\/p><p>- системные администраторы;<\\/p><p>- DevOps-инженеры;<\\/p><p>- администраторы серверов;<\\/p><p>- разработчики.<\\/p><p>Терминал позволяет выполнять работу значительно быстрее и автоматизировать повторяющиеся действия.<\\/p><p>Весь данный курс посвящён именно работе в терминале Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое командная оболочка (Shell)<\\/strong><\\/p><p>Shell — это программа, которая получает команды пользователя, обрабатывает их и передаёт ядру Linux.<\\/p><p>Последовательность работы выглядит так:<\\/p><p>- Пользователь вводит команду.<\\/p><p>- Shell анализирует её.<\\/p><p>- Shell обращается к ядру Linux.<\\/p><p>- Ядро выполняет необходимое действие.<\\/p><p>- Результат возвращается обратно в терминал.<\\/p><p>&nbsp;<\\/p><p>Таким образом, терминал и Shell — это разные понятия.<\\/p><p>Терминал — окно для ввода команд.<\\/p><p>Shell — программа, которая эти команды выполняет.<\\/p><p>&nbsp;<\\/p><p><strong>Почему в курсе используется Bash<\\/strong><\\/p><p>Существует несколько командных оболочек Linux.<\\/p><p>Несмотря на различия, большинство основных команд Linux работают одинаково во всех оболочках.<\\/p><p>В этом курсе используется Bash по следующим причинам:<\\/p><p>- она установлена практически во всех дистрибутивах Linux;<\\/p><p>- используется на большинстве серверов;<\\/p><p>- применяется в GitHub Codespaces;<\\/p><p>- именно Bash чаще всего встречается в документации и учебных материалах;<\\/p><p>- она является промышленным стандартом для большинства серверных систем.<\\/p><p>Изучив Bash, вы без труда сможете работать и с другими оболочками Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>Изучайте Linux через регулярную практику в терминале.<\\/p><p>Не бойтесь экспериментировать в учебной среде.<\\/p><p>Старайтесь понимать смысл каждой команды, а не просто запоминать её.<\\/p><p>Используйте официальную документацию при изучении новых возможностей Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>Считать Linux исключительно системой для программистов.<\\/p><p>Пытаться выполнять административные действия без понимания их последствий.<\\/p><p>Заучивать команды без практики.<\\/p><p>Бояться использовать терминал вместо графического интерфейса.<\\/p>\",\"tests\":[{\"question\":\"Что такое Linux?\",\"answers\":[\"Программа для создания сайтов\",\"Операционная система\",\"Язык программирования\",\"Текстовый редактор\"],\"correct\":1},{\"question\":\"Что такое ядро Linux?\",\"answers\":[\"Файловый менеджер в ОС Linux\",\"Основная часть операционной системы\",\"Командная оболочка дистрибутива Linux\",\"Редактор программ\"],\"correct\":1},{\"question\":\"Что такое терминал?\",\"answers\":[\"Антивирус\",\"Окно для ввода команд\",\"База данных в ОС Linux\",\"Веб-браузер в ОС Linux\"],\"correct\":1},{\"question\":\"Что делает Shell?\",\"answers\":[\"Хранит файлы в оболочке\",\"Выполняет команды пользователя\",\"Подключает Интернет в защищённой оболочке\",\"Компилирует программы\"],\"correct\":1},{\"question\":\"Где чаще всего используется Linux?\",\"answers\":[\"Только на домашних компьютерах\",\"Только в игровых приставках\",\"На серверах, в облаках и дата-центрах\",\"Только в мобильных телефонах\"],\"correct\":2},{\"question\":\"Что является основной особенностью Linux?\",\"answers\":[\"Платная лицензия\",\"Закрытый исходный код\",\"Открытый исходный код\",\"Работа только без Интернета\"],\"correct\":2},{\"question\":\"Что делает ядро Linux?\",\"answers\":[\"Управляет оборудованием компьютера\",\"Создаёт веб-страницы\",\"Редактирует документы\",\"Устанавливает браузеры\"],\"correct\":0},{\"question\":\"Чем терминал отличается от Shell?\",\"answers\":[\"Это одно и то же\",\"Терминал — окно ввода команд, Shell — программа их обработки\",\"Shell — окно ввода команд, Терминал — программа их обработки\",\"Терминал является ядром Linux, а Shell - оболочкой для взаимодействия с ядром.\"],\"correct\":1}],\"tasks\":[{\"task\":\"Нарисуйте схему взаимодействия пользователя, терминала, Shell, ядра Linux и оборудования.\"},{\"task\":\"Сравните Linux и Windows по трём критериям: лицензия, безопасность и области применения.\"},{\"task\":\"Найдите информацию о командных оболочках Bash, Zsh и Fish и расскажите их основные отличия.\"}]}', 1),
(6, 'GitHub и GitHub Codespaces. Начало работы в терминале Codespaces', 'codespaces', 2, '{\"theory\":\"<p><strong>Что такое GitHub<\\/strong><\\/p><p>Перед изучением команд Linux необходимо подготовить рабочую среду. В этом курсе вся практика будет выполняться в GitHub Codespaces.<\\/p><p>GitHub — это крупнейший сервис для хранения проектов и совместной разработки программного обеспечения. Он хранит проекты в специальных хранилищах — репозиториях.<\\/p><p>GitHub позволяет:<\\/p><p>- хранить исходный код проекта;<\\/p><p>- отслеживать историю изменений;<\\/p><p>- работать над одним проектом нескольким разработчикам одновременно;<\\/p><p>- создавать резервную копию проекта в интернете;<\\/p><p>- запускать облачную среду разработки GitHub Codespaces.<\\/p><p>Практически любой современный разработчик использует GitHub.<\\/p><p>&nbsp;<\\/p><p><strong>Регистрация на GitHub<\\/strong><\\/p><p>Для работы потребуется бесплатная учетная запись.<\\/p><p>Откройте сайт <a href=\\\"https:\\/\\/github.com\\/\\\">https:\\/\\/github.com<\\/a>.<\\/p><p>Нажмите Sign up.<\\/p><p>Нажмите \\\"Continue with Google\\\".<\\/p><p>Укажите свой Google-аккаунт.<\\/p><p>Пройдите процесс регистрации.<\\/p><p>Подтвердите регистрацию и войдите в свою учетную запись.<\\/p><p>После входа откроется главная страница GitHub.<\\/p><p>&nbsp;<\\/p><p><strong>Создание репозитория<\\/strong><\\/p><p>Репозиторий — это место, где хранятся файлы проекта.<\\/p><p>Для создания репозитория:<\\/p><p>Нажмите New.<\\/p><p>Введите имя репозитория: linux-course<\\/p><p>Оставьте репозиторий Public.&nbsp;&nbsp;&nbsp;&nbsp;<\\/p><p>Поставьте галочку Add a README file.<\\/p><p>Нажмите Create repository.<\\/p><p>После этого откроется страница нового репозитория.<\\/p><p>На данном этапе внутри будет всего один файл:<\\/p><p>README.md<\\/p><p>Позже здесь появятся все файлы, создаваемые во время курса.<\\/p><p>&nbsp;<\\/p><p><strong>Создание GitHub Codespace<\\/strong><\\/p><p>GitHub Codespaces — это полноценный компьютер с Linux, который работает в облаке.<\\/p><p>Вам не нужно устанавливать Linux на свой компьютер.<\\/p><p>Для создания Codespace:<\\/p><p>Откройте страницу своего репозитория.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (хотя она у вас уже открыта)<\\/p><p>Нажмите кнопку Code.<\\/p><p>Перейдите на вкладку Codespaces.<\\/p><p>Нажмите Create codespace on main.<\\/p><p>Подождите примерно одну минуту.<\\/p><p>Через некоторое время откроется окно редактора.<\\/p><p>GitHub автоматически создаст виртуальную машину Ubuntu и подготовит рабочую среду.<\\/p><p>&nbsp;<\\/p><p>Теперь можно выполнять команды Linux прямо в браузере.<\\/p><p>(не обращайте внимание на странный адрес в адресной строке, типа: https:\\/\\/musical-space-fishstick-x54j7gj4w457cp5wp.github.dev\\/)<\\/p><p>&nbsp;<\\/p><p><strong>Интерфейс GitHub Codespaces<\\/strong><\\/p><p>После запуска Codespace вы увидите несколько основных областей.<\\/p><p>&nbsp;<\\/p><p>Проводник файлов (Explorer)<\\/p><p>Расположен слева.<\\/p><p>Показывает все файлы и каталоги проекта.<\\/p><p>Здесь можно создавать новые файлы и открывать существующие.<\\/p><p>&nbsp;<\\/p><p>Редактор<\\/p><p>Находится в центре окна.<\\/p><p>В нем открываются файлы для просмотра и редактирования.<\\/p><p>Можно одновременно открыть несколько файлов.<\\/p><p>&nbsp;<\\/p><p>Терминал<\\/p><p>Расположен обычно в нижней части окна.<\\/p><p>Именно здесь будут выполняться все команды Linux.<\\/p><p>&nbsp;<\\/p><p>В следующих лекциях практически вся работа будет происходить именно в терминале.<\\/p><p>&nbsp;<\\/p><p>Панель активности<\\/p><p>Находится слева вертикально.<\\/p><p>Позволяет быстро переключаться между:<\\/p><p>Explorer<\\/p><p>Search<\\/p><p>Source Control<\\/p><p>Extensions<\\/p><p>и другими инструментами.<\\/p><p>&nbsp;<\\/p><p>На первых этапах курса вам почти всегда понадобится только Explorer и Terminal.<\\/p><p>&nbsp;<\\/p><p>Строка состояния<\\/p><p>Находится внизу окна.<\\/p><p>Показывает информацию о текущем Codespace, подключении и состоянии среды разработки.<\\/p><p>&nbsp;<\\/p><p><strong>Терминал<\\/strong><\\/p><p>Терминал — это окно, в котором пользователь вводит команды Linux и сразу получает результат их выполнения.<\\/p><p>Именно через терминал системные администраторы, DevOps-инженеры, программисты и специалисты по информационной безопасности ежедневно работают с Linux.<\\/p><p>В GitHub Codespaces терминал уже открыт в нижней части окна. Если его нет, открыть его можно через меню Terminal → New Terminal.<\\/p><p>&nbsp;<\\/p><p>После открытия терминала обычно отображается приглашение командной строки, например:<\\/p><p><code>&lt;ваше_имя_на_github&gt; ➜ \\/workspaces\\/ linux-course $<\\/code><\\/p><p>Это означает, что терминал готов принимать команды.<\\/p><p>Команда вводится после символа $, затем нажимается клавиша Enter.<\\/p><p>&nbsp;<\\/p><p>Например, напишите команду:<\\/p><p><code>pwd<\\/code><\\/p><p>После нажатия клавиши Enter - Linux выполнит команду и выведет результат.<\\/p><p>Практически вся работа в этом курсе будет выполняться именно в терминале.<\\/p><p>&nbsp;<\\/p><p><strong>Домашний каталог пользователя<\\/strong><\\/p><p>После открытия терминала пользователь всегда находится в своём домашнем каталоге.<\\/p><p>Домашний каталог — это место, где обычно хранятся личные файлы пользователя.<\\/p><p>В GitHub Codespaces именно отсюда начинается работа с системой.<\\/p><p>В дальнейшем практически все примеры курса будут выполняться относительно домашнего каталога.<\\/p><p>Пока не нужно запоминать его полное имя. Достаточно понимать, что после запуска терминала вы уже находитесь в своём рабочем месте.<\\/p><p>&nbsp;<\\/p><p><strong>Структура команд Linux<\\/strong><\\/p><p>Большинство команд Linux имеют одинаковую структуру.<\\/p><p><code>команда [параметры] [аргументы]<\\/code><\\/p><p>Команда — определяет, что необходимо сделать.<\\/p><p>Параметры (опции) — изменяют поведение команды.<\\/p><p>Аргументы — указывают, с чем должна работать команда.<\\/p><p>Например:<\\/p><p><code>команда параметр аргумент<\\/code><\\/p><p>Не каждая команда использует одновременно параметры и аргументы.<\\/p><p>Например, команда:<\\/p><p><code>pwd<\\/code><\\/p><p>не имеет ни параметров, ни аргументов.<\\/p><p>В дальнейшем вы познакомитесь с командами, которые используют и параметры и аргументы.<\\/p><p>&nbsp;<\\/p><p>Главное правило:<\\/p><p>Сначала вводится имя команды.<\\/p><p>Затем, если нужно, параметры.<\\/p><p>После этого указываются аргументы.<\\/p><p>Такая схема используется практически во всём Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Удалять репозиторий, не убедившись, что в нем нет важных файлов.<\\/p><p>- Не вводите команды, не понимая, где находитесь.<\\/p><p>- Не путайте терминал и редактор кода — они предназначены для разных задач.<\\/p><p>- Не изменяйте случайные файлы только потому, что они видны в проводнике.<\\/p><p>- Не игнорируйте сообщения терминала — они помогают понять, что произошло.<\\/p><p>- Не предполагайте своё текущее местоположение — всегда проверяйте его командой pwd.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Создавайте отдельный репозиторий для каждого учебного проекта.<\\/p><p>- Давайте репозиториям понятные имена.<\\/p><p>- Используйте один Codespace для выполнения заданий текущего курса.<\\/p><p>- Перед выполнением команд всегда смотрите, в каком каталоге вы находитесь.<\\/p><p>- Если получен неожиданный результат, сначала выполните pwd.<\\/p><p>- Работайте преимущественно через терминал — это быстрее и удобнее при автоматизации.<\\/p><p>- Используйте проводник файлов для просмотра структуры проекта, а терминал — для выполнения операций.<\\/p><p>- Привыкайте внимательно читать приглашение командной строки перед вводом команды.<\\/p>\",\"tests\":[{\"question\":\"Что такое GitHub?\",\"answers\":[\"Облачное хранилище фотографий\",\"Сервис хранения и совместной разработки проектов\",\"Дистрибутив операционной системы Linux\",\"Текстовый редактор в операционной системе Linux\"],\"correct\":1},{\"question\":\"Как называется место хранения проекта на GitHub?\",\"answers\":[\"Каталог\",\"Репозиторий\",\"Архив\",\"Контейнер\"],\"correct\":1},{\"question\":\"Что необходимо сделать перед созданием Codespace?\",\"answers\":[\"Установить Ubuntu\",\"Создать репозиторий\",\"Купить платную подписку\",\"Установить Visual Studio\"],\"correct\":1},{\"question\":\"Где создается GitHub Codespace?\",\"answers\":[\"На домашнем компьютере\",\"В браузере на облачном сервере GitHub\",\"На веб-сайте\",\"В кодовом пространстве\"],\"correct\":1},{\"question\":\"Для чего используется репозиторий?\",\"answers\":[\"Для хранения файлов проекта\",\"Для хранения паролей\",\"Для установки Linux\",\"Для настройки браузера\"],\"correct\":0},{\"question\":\"Как называется команда, показывающая текущий каталог?\",\"answers\":[\"where\",\"pwd\",\"path\",\"dir\"],\"correct\":1},{\"question\":\"Что вводится первым в команде Linux?\",\"answers\":[\"Аргумент\",\"Параметр\",\"Имя команды\",\"Путь к файлу\"],\"correct\":2}],\"tasks\":[{\"task\":\"Самостоятельно изучите рабочую среду GitHub Codespaces, все её части, окна, кнопки\"}]}', 1),
(7, 'Первые команды Linux', 'first-commands', 3, '{\"theory\":\"<p>После предыдущей лекции вы уже умеете открывать терминал GitHub Codespaces, знаете, что такое домашний каталог пользователя, и знакомы с командой pwd. Теперь начнём непосредственно работать с Linux из терминала.<\\/p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<\\/p><p>В этой лекции изучим четыре базовые команды:<\\/p><p>pwd — узнать, в каком каталоге мы сейчас находимся<\\/p><p>cd — перейти в другой каталог<\\/p><p>ls — посмотреть содержимое каталога<\\/p><p>whoami — узнать имя текущего пользователя<\\/p><p>&nbsp;<\\/p><p>Также освоим четыре приёма, которые постоянно используются при работе в терминале:<\\/p><p>автодополнение клавишей Tab<\\/p><p>перемещение по истории команд клавишами ↑ и ↓<\\/p><p>очистка терминала клавишами Ctrl+L<\\/p><p>прерывание выполняемой команды клавишами Ctrl+C<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды GitHub Codespaces<\\/strong><\\/p><p>Откройте GitHub Codespaces и терминал.<\\/p><p>Для практических примеров подготовим небольшую учебную структуру каталогов и файлов. Эти команды нужны только для подготовки среды. Команды mkdir и touch подробно будут изучаться позже.<\\/p><p>Скопируйте весь блок целиком и выполните его в терминале:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p ~\\/linux-course\\/lesson3\\/projects\\r\\nmkdir -p ~\\/linux-course\\/lesson3\\/docs\\r\\nmkdir -p ~\\/linux-course\\/lesson3\\/config\\r\\ntouch ~\\/linux-course\\/lesson3\\/projects\\/app.txt\\r\\ntouch ~\\/linux-course\\/lesson3\\/docs\\/readme.txt\\r\\ntouch ~\\/linux-course\\/lesson3\\/config\\/settings.conf<\\/code><\\/pre><p>&nbsp;<\\/p><p>После выполнения структура будет примерно такой:<\\/p><pre><code class=\\\"language-plaintext\\\">linux-course\\/\\r\\n└── lesson3\\/\\r\\n &nbsp;&nbsp; ├── projects\\/\\r\\n &nbsp;&nbsp; │&nbsp;&nbsp; └── app.txt\\r\\n &nbsp;&nbsp; ├── docs\\/\\r\\n &nbsp;&nbsp; │&nbsp;&nbsp; └── readme.txt\\r\\n &nbsp;&nbsp; └── config\\/\\r\\n &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; └── settings.conf<\\/code><\\/pre><p>Перейдите в подготовленный каталог:<\\/p><p><code>cd ~\\/linux-course\\/lesson3<\\/code><\\/p><p>Проверьте своё местоположение:<\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>Возможен другой путь к домашнему каталогу. Это нормально. Главное, что в конце пути находится:<\\/p><p><code>\\/linux-course\\/lesson3<\\/code><\\/p><p>Теперь учебная среда готова.<\\/p><p>&nbsp;<\\/p><p><strong>Команда pwd<\\/strong><\\/p><p>pwd показывает полный путь к каталогу, в котором сейчас находится терминал.<\\/p><p>Название команды происходит от английского print working directory — «вывести рабочий каталог».<\\/p><p>Это одна из самых полезных команд для начинающего пользователя. Если вы потеряли ориентацию в файловой системе и не понимаете, где находитесь, первым делом выполните: pwd<\\/p><p>Синтаксис :<\\/p><p><code>pwd<\\/code><\\/p><p>Для обычной работы в курсе достаточно запомнить именно этот вариант.<\\/p><p>На этом этапе параметры pwd не нужны. Команда без параметров полностью решает основную задачу: показывает текущий каталог.<\\/p><p>Когда используется на практике?<\\/p><p>pwd используется, когда необходимо быстро проверить текущее местоположение.<\\/p><p>Например, разработчик работает в большом проекте и несколько раз переходил между каталогами. Перед выполнением следующей команды полезно проверить, где он находится.<\\/p><p>Также pwd помогает понять, какой каталог является текущим рабочим каталогом для последующих команд.<\\/p><p>Пример. Перейти в каталог projects и проверить положение<\\/p><p><code>cd projects<\\/code><\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Вернуться в каталог lesson3 и проверить путь<\\/p><p>Здесь используется специальное обозначение<\\/p><p><code>..<\\/code><\\/p><p>Оно означает родительский каталог, то есть каталог на один уровень выше текущего.<\\/p><p><code>cd ..<\\/code><\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>Таким образом, команда pwd отвечает на очень простой вопрос:<\\/p><p>«Где я сейчас нахожусь?»<\\/p><p>&nbsp;<\\/p><p><strong>Очистка экрана: Ctrl+L<\\/strong><\\/p><p>Со временем терминал заполняется большим количеством текста.<\\/p><p>Чтобы очистить видимую область терминала, нажмите:<\\/p><p><code>Ctrl+L<\\/code><\\/p><p>Это не удаляет файлы, не отменяет выполненные команды и не очищает историю.<\\/p><p>Комбинация просто делает экран терминала чистым и удобным для дальнейшей работы.<\\/p><p>После очистки можно снова выполнить:<\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>Ctrl+L удобно использовать перед началом новой практической задачи, когда старый вывод уже мешает ориентироваться.<\\/p><p>&nbsp;<\\/p><p><strong>Команда cd<\\/strong><\\/p><p>cd изменяет текущий рабочий каталог терминала.<\\/p><p>Название происходит от change directory — «изменить каталог».<\\/p><p>В графическом файловом менеджере мы открываем папки мышью. В терминале аналогичное действие выполняется командой cd.<\\/p><p>Синтаксис<\\/p><p><code>cd каталог<\\/code><\\/p><p>После cd указывается путь к каталогу, в который нужно перейти.<\\/p><p>Например:<\\/p><p><code>cd projects<\\/code><\\/p><p>&nbsp;<\\/p><p>В базовом использовании cd не имеет параметров в том смысле, как их имеют многие другие команды.&nbsp;<\\/p><p>После команды указывается путь к каталогу.<\\/p><p>Особенно важно запомнить:<\\/p><p><code>..&nbsp;&nbsp;&nbsp;<\\/code><\\/p><p>(две точки - это родительский каталог)<\\/p><p>Например, если мы находимся здесь:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>то:<\\/p><p><code>cd ..<\\/code><\\/p><p>переместит нас сюда:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>cd используется постоянно. Перед выполнением многих команд разработчик сначала переходит в нужный каталог.<\\/p><p>Например:<\\/p><p>- перейти в каталог проекта<\\/p><p>- перейти в каталог с конфигурацией<\\/p><p>- перейти в каталог с документацией<\\/p><p>- вернуться на уровень выше<\\/p><p>&nbsp;<\\/p><p>Пример. Перейти в projects<\\/p><p>Сначала убедимся, что находимся в lesson3:<\\/p><pre><code class=\\\"language-plaintext\\\">cd ~\\/linux-course\\/lesson3\\r\\ncd projects\\r\\npwd<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Вернуться на один уровень вверх<\\/p><pre><code class=\\\"language-plaintext\\\">cd ..\\r\\npwd<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Перейти в docs<\\/p><pre><code class=\\\"language-plaintext\\\">cd docs\\r\\npwd<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Перейти в config<\\/p><p>Сначала вернёмся в lesson3, затем перейдём в config:<\\/p><pre><code class=\\\"language-plaintext\\\">cd ..\\r\\ncd config\\r\\npwd<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/config<\\/code><\\/p><p>&nbsp;<\\/p><p>Важное правило<\\/p><p>Если вы не уверены, где находитесь, не пытайтесь угадывать.<\\/p><p>Выполните: pwd<\\/p><p>Затем уже решайте, какой cd нужен.<\\/p><p>&nbsp;<\\/p><p><strong>Команда ls<\\/strong><\\/p><p>ls показывает содержимое текущего каталога.<\\/p><p>Название связано с английским list — «список».<\\/p><p>Если pwd отвечает на вопрос:<\\/p><p>«Где я нахожусь?»<\\/p><p>то ls отвечает:<\\/p><p>«Что находится в этом каталоге?»<\\/p><p>Синтаксис<\\/p><p><code>ls<\\/code><\\/p><p>Также можно указать каталог:<\\/p><p><code>ls каталог<\\/code><\\/p><p>&nbsp;<\\/p><p>В этой лекции (специально, чтобы не усложнять) используем базовую форму ls без опций.<\\/p><p>Подробные варианты ls, включая -l, -a и -la, будут изучаться в следующей лекции.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>- ls применяется постоянно:<\\/p><p>- чтобы посмотреть файлы проекта<\\/p><p>- чтобы увидеть доступные каталоги<\\/p><p>- чтобы проверить, существует ли нужный файл<\\/p><p>- чтобы быстро сориентироваться в структуре проекта<\\/p><p>&nbsp;<\\/p><p>Пример. Посмотреть содержимое lesson3<\\/p><p>Перейдём в каталог урока:<\\/p><pre><code class=\\\"language-plaintext\\\">cd ~\\/linux-course\\/lesson3\\r\\nls<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>config&nbsp; docs&nbsp; projects<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Посмотреть содержимое projects<\\/p><p><code>ls projects<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>app.txt<\\/code><\\/p><p>Обратите внимание: мы не переходили в projects. Мы попросили ls показать содержимое конкретного каталога.<\\/p><p>&nbsp;<\\/p><p>Пример. Посмотреть содержимое docs<\\/p><p><code>ls docs<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>readme.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Связка pwd и ls особенно полезна:<\\/p><p><code>pwd<\\/code><\\/p><p><code>ls<\\/code><\\/p><p>Сначала мы узнаём, где находимся, а затем смотрим, что находится в этом месте.<\\/p><p>&nbsp;<\\/p><p><strong>Команда whoami<\\/strong><\\/p><p>whoami показывает имя пользователя, от имени которого сейчас выполняются команды.<\\/p><p>Название происходит от английской фразы who am I — «кто я».<\\/p><p>Синтаксис:<\\/p><p><code>whoami<\\/code><\\/p><p>Параметры у этой команды есть, но для базового использования параметры не нужны.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>Команда полезна, когда нужно быстро определить текущего пользователя.<\\/p><p>Это особенно важно на сервере или в Codespaces, где имя пользователя может быть неочевидным.<\\/p><p>При диагностике проблем с доступом к файлам также полезно сначала проверить, от имени какого пользователя выполняется работа.<\\/p><p>&nbsp;<\\/p><p>Пример. Узнать текущего пользователя<\\/p><p><code>whoami<\\/code><\\/p><p>Ожидаемый вывод может выглядеть так:<\\/p><p><code>codespace<\\/code><\\/p><p>Точное имя пользователя может отличаться.<\\/p><p>&nbsp;<\\/p><p>Пример. Использовать whoami вместе с pwd<\\/p><p><code>whoami<\\/code><\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод может выглядеть так:<\\/p><p><code>codespace<\\/code><\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p>Теперь мы знаем одновременно:<\\/p><p>кто выполняет команды<\\/p><p>где этот пользователь находится<\\/p><p>&nbsp;<\\/p><p>Пример. Быстро проверить окружение Codespaces<\\/p><pre><code class=\\\"language-plaintext\\\">whoami\\r\\npwd\\r\\nls<\\/code><\\/pre><p>Ожидаемый вывод может выглядеть так:<\\/p><p><code>codespace<\\/code><\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3<\\/code><\\/p><p><code>config&nbsp; docs&nbsp; projects<\\/code><\\/p><p>Это уже небольшой практический алгоритм диагностики:<\\/p><p>- сначала определить пользователя<\\/p><p>- затем определить текущий каталог<\\/p><p>- затем посмотреть содержимое каталога<\\/p><p>&nbsp;<\\/p><p><strong>Как команды работают вместе<\\/strong><\\/p><p>Отдельные команды полезны, но настоящая работа в терминале начинается тогда, когда мы используем их последовательно.<\\/p><p>Например:<\\/p><pre><code class=\\\"language-plaintext\\\">cd projects\\r\\npwd\\r\\nls\\r\\nwhoami<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p><code>app.txt &nbsp;<\\/code><\\/p><p><code>codespace<\\/code><\\/p><p>Четыре команды дают четыре разных вида информации.<\\/p><p>&nbsp;<\\/p><p>Вернитесь в каталог урока:<\\/p><p><code>cd ..<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Автодополнение клавишей Tab<\\/strong><\\/p><p>В терминале необязательно каждый раз полностью печатать имя каталога.<\\/p><p>Начните вводить название и нажмите Tab.<\\/p><p>Например, находясь в lesson3, введите:<\\/p><p><code>cd pro<\\/code><\\/p><p>Затем нажмите Tab.<\\/p><p>Если имя однозначно, Bash дополнит его:<\\/p><p><code>cd projects<\\/code><\\/p><p>После этого можно нажать Enter.<\\/p><p>Проверить результат:<\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>Автодополнение особенно полезно для длинных имён. Оно уменьшает количество ручного ввода и вероятность опечатки.<\\/p><p>Если введённой части недостаточно для однозначного выбора, первое нажатие Tab может не завершить слово. В таком случае продолжите вводить имя и используйте Tab повторно.<\\/p><p>&nbsp;<\\/p><p><strong>История команд: ↑ и ↓<\\/strong><\\/p><p>Bash сохраняет команды, которые вы уже вводили.<\\/p><p>Клавиша ↑ показывает предыдущую команду.<\\/p><p>Если нажимать ↑ несколько раз, можно перемещаться назад по истории.<\\/p><p>Клавиша ↓ перемещает вперёд по истории.<\\/p><p>Например, выполните:<\\/p><p><code>pwd<\\/code><\\/p><p>затем:<\\/p><p><code>ls<\\/code><\\/p><p>затем:<\\/p><p><code>whoami<\\/code><\\/p><p>Теперь нажмите ↑ несколько раз.<\\/p><p>В строке ввода будут появляться ранее выполненные команды.<\\/p><p>Это позволяет не набирать длинную команду заново.<\\/p><p>Например, если вы недавно выполняли:<\\/p><p><code>cd ~\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>необязательно печатать её снова. Нажмите ↑, найдите нужную команду и нажмите Enter.<\\/p><p>История команд особенно полезна при повторении одной и той же операции.<\\/p><p>&nbsp;<\\/p><p><strong>Прерывание команды: Ctrl+C<\\/strong><\\/p><p>Иногда команда выполняется дольше, чем ожидалось, или вы случайно запустили не то действие.<\\/p><p>Для прерывания текущего действия используется:<\\/p><p><code>Ctrl+C<\\/code><\\/p><p>Важно понимать: Ctrl+C относится к текущему процессу или текущему вводу в терминале. Это не команда удаления файла и не команда закрытия Codespaces.<\\/p><p>Например, начните вводить:<\\/p><p><code>cd ~\\/linux-course\\/lesson3\\/projects<\\/code><\\/p><p>но перед нажатием Enter нажмите:<\\/p><p><code>Ctrl+C<\\/code><\\/p><p>Ввод будет отменён, и вы снова получите приглашение терминала.<\\/p><p>Этот приём особенно важен в реальной работе: если команда выполняется не так, как ожидалось, Ctrl+C часто является первым способом остановить её.<\\/p><p>На следующих этапах курса Ctrl+C будет особенно полезен при работе с командами, которые могут выполняться длительное время.<\\/p><p>&nbsp;<\\/p><p><strong>Четыре главные команды лекции<\\/strong><\\/p><p>Запомните основную роль каждой команды:<\\/p><p>pwd&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; где я нахожусь<\\/p><p>cd&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; перейти в другой каталог<\\/p><p>ls&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; что находится в каталоге<\\/p><p>whoami&nbsp;&nbsp;&nbsp; от имени какого пользователя я работаю<\\/p><p>Удобно мыслить ими как четырьмя базовыми вопросами:<\\/p><p>whoami&nbsp;&nbsp;&nbsp; Кто я?<\\/p><p>pwd&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Где я?<\\/p><p>ls&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Что здесь?<\\/p><p>cd&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Куда перейти?<\\/p><p>Если вы научитесь уверенно использовать эти четыре команды, работа с терминалом станет значительно понятнее.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Пытаться угадывать текущий каталог вместо использования pwd. Это часто приводит к выполнению команды не в том месте.<\\/p><p>- Печатать длинные имена каталогов вручную, когда можно использовать Tab. Ручной ввод увеличивает вероятность опечатки.<\\/p><p>- Переходить по каталогам вслепую и не проверять результат. После важных переходов полезно выполнить pwd.<\\/p><p>- Игнорировать содержимое каталога перед началом работы. Быстрый ls помогает понять, где вы находитесь и что доступно.<\\/p><p>- Продолжать ждать команду, если она явно выполняется не так, как ожидалось. В подходящей ситуации используйте Ctrl+C для прерывания.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- После перехода в важный каталог проверяйте положение командой pwd. Это особенно полезно перед дальнейшими действиями.<\\/p><p>- Используйте ls, чтобы сначала осмотреть каталог. Не работайте с неизвестной структурой вслепую.<\\/p><p>- Используйте Tab для длинных имён каталогов. Это быстрее и снижает количество ошибок.<\\/p><p>- Используйте ↑ и ↓ для повторения уже введённых команд. Не набирайте одну и ту же длинную команду вручную несколько раз.<\\/p><p>- Используйте Ctrl+L для очистки экрана, когда старый вывод мешает работе.<\\/p><p>- Если текущая команда явно выполняется неправильно, используйте Ctrl+C, чтобы остановить её.<\\/p>\",\"tests\":[{\"question\":\"Что показывает команда pwd?\",\"answers\":[\"Имя текущего пользователя\",\"Содержимое текущего каталога\",\"Полный путь текущего рабочего каталога\",\"Список всех процессов Linux\"],\"correct\":2},{\"question\":\"Какая команда используется для перехода в другой каталог?\",\"answers\":[\"ls\",\"cd\",\"pwd\",\"whoami\"],\"correct\":1},{\"question\":\"Что показывает команда ls без параметров?\",\"answers\":[\"Текущий путь\",\"Имя пользователя\",\"Содержимое каталога\",\"Версию Linux\"],\"correct\":2},{\"question\":\"Что делает команда whoami?\",\"answers\":[\"Показывает имя текущего пользователя\",\"Показывает домашний каталог\",\"Переходит в каталог пользователя\",\"Показывает содержимое домашнего каталога\"],\"correct\":0},{\"question\":\"Что означает .. при работе с cd?\",\"answers\":[\"Текущий файл\",\"Родительский каталог\",\"Домашний каталог пользователя\",\"Корневой каталог Linux\"],\"correct\":1},{\"question\":\"Вы находитесь в каталоге projects. Как перейти на уровень выше?\",\"answers\":[\"cd \\/\",\"cd ..\",\"pwd\",\"ls ..\"],\"correct\":1},{\"question\":\"Для чего используется клавиша Tab в терминале?\",\"answers\":[\"Для очистки экрана\",\"Для остановки команды\",\"Для автоматического дополнения ввода\",\"Для удаления предыдущей команды\"],\"correct\":2},{\"question\":\"Что произойдёт при нажатии ↑ в Bash?\",\"answers\":[\"Будет очищен экран\",\"Будет выполнена последняя команда автоматически\",\"Появится предыдущая команда из истории\",\"Текущий каталог изменится\"],\"correct\":2},{\"question\":\"Какая комбинация очищает видимую область терминала?\",\"answers\":[\"Ctrl+C\",\"Ctrl+L\",\"Ctrl+R\",\"Ctrl+D\"],\"correct\":1},{\"question\":\"Что обычно следует сделать, если текущую выполняемую команду необходимо остановить?\",\"answers\":[\"Нажать Ctrl+C\",\"Нажать Ctrl+L и ждать\",\"Выполнить pwd\",\"Нажать Tab несколько раз\"],\"correct\":0}],\"tasks\":[{\"task\":\"Находясь в ~\\/linux-course\\/lesson3, с помощью ls определите названия трёх каталогов учебной структуры. Затем по очереди посмотрите содержимое каждого из них.\"},{\"task\":\"Составьте и выполните собственный маршрут по учебной структуре: начните в lesson3, посетите projects, docs и config, используя только изученные команды cd, pwd и ls. На каждом этапе определяйте текущее положение и содержимое каталога, а для длинных имён используйте Tab.\"}]}', 1);
INSERT INTO `lessons` (`id`, `title_ru`, `slug`, `lesson_order`, `content`, `is_published`) VALUES
(8, 'Просмотр каталогов (ls)', 'browse-directories', 4, '{\"theory\":\"<p>В предыдущей лекции мы познакомились с командой ls и использовали её для просмотра содержимого каталога. Теперь разберём эту команду подробнее. Научимся получать подробный список файлов, видеть скрытые файлы и понимать, как устроено содержимое домашнего каталога пользователя в Linux.<\\/p><p>Для работы будем использовать GitHub Codespaces.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды<\\/strong><\\/p><p>Откройте терминал в вашем GitHub Codespaces.<\\/p><p>Для практических примеров нам понадобится небольшая учебная структура каталогов и файлов. В реальной работе такие каталоги и файлы будут уже существовать в вашем проекте. Здесь мы создадим отдельную учебную область.<\\/p><p>&nbsp;<\\/p><p>Скопируйте весь следующий блок команд и выполните его в терминале:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir lesson4\\r\\ncd lesson4\\r\\nmkdir documents scripts logs\\r\\ntouch README.md notes.txt config.conf\\r\\ntouch .env .hidden<\\/code><\\/pre><p>После выполнения мы получим примерно такую структуру:<\\/p><pre><code class=\\\"language-plaintext\\\">lesson4\\/\\r\\n├── documents\\/\\r\\n├── scripts\\/\\r\\n├── logs\\/\\r\\n├── README.md\\r\\n├── notes.txt\\r\\n├── config.conf\\r\\n├── .env\\r\\n└── .hidden<\\/code><\\/pre><p>Команды mkdir и touch пока не являются темой данной лекции. Они использованы здесь только для первоначальной подготовки учебной среды. Подробно изучать как создавать каталоги и файлы мы будем в следующих лекциях.<\\/p><p>Проверьте текущий каталог:<\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><p><code>\\/workspaces\\/имя-репозитория\\/lesson4<\\/code><\\/p><p>Точный путь зависит от имени вашего репозитория и пользователя.<\\/p><p>Теперь можно переходить к основной теме.<\\/p><p>&nbsp;<\\/p><p><strong>Команда ls<\\/strong><\\/p><p>ls показывает содержимое каталога.<\\/p><p>Название команды происходит от слова list, то есть «список».<\\/p><p>Если выполнить без параметров:<\\/p><p><code>ls<\\/code><\\/p><p>Linux покажет файлы и каталоги текущего каталога.<\\/p><p>В нашей учебной структуре обычный вывод будет похож на:<\\/p><p>README.md&nbsp; config.conf&nbsp; documents&nbsp; logs&nbsp; notes.txt&nbsp; scripts<\\/p><p>Обратите внимание: файлов .env и .hidden здесь нет.<\\/p><p>Это не означает, что их не существует. Они являются скрытыми файлами, а обычный ls по умолчанию их не показывает.<\\/p><p>Также можно указать каталог, содержимое которого нужно посмотреть:<\\/p><p><code>ls documents<\\/code><\\/p><p>В этом случае ls покажет содержимое каталога documents, а не текущего каталога.<\\/p><p>&nbsp;<\\/p><p>Команда ls используется постоянно.<\\/p><p>Перед выполнением операций с файлами разработчик часто сначала смотрит, что находится в текущем каталоге.<\\/p><p>Команда особенно полезна при работе через терминал, когда файловый интерфейс недоступен или нужно быстро проверить структуру проекта.<\\/p><p>&nbsp;<\\/p><p>Практический пример<\\/p><p>Посмотрим содержимое конкретного каталога:<\\/p><p><code>ls documents<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p>Каталог пока пуст, поэтому команда ничего не выводит.<\\/p><p>&nbsp;<\\/p><p><strong>Опция -l<\\/strong><\\/p><p>Опция -l включает подробный, или длинный, формат вывода.<\\/p><p>Без -l команда показывает в основном имена элементов.<\\/p><p>С -l Linux выводит дополнительную информацию о каждом элементе.<\\/p><p>Выполните:<\\/p><p><code>ls -l<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><pre><code class=\\\"language-plaintext\\\">total 0\\r\\n-rw-r--r-- 1 vscode vscode 0 Jul 25 12:00 README.md\\r\\n-rw-r--r-- 1 vscode vscode 0 Jul 25 12:00 config.conf\\r\\ndrwxr-xr-x 2 vscode vscode 6 Jul 25 12:00 documents\\r\\ndrwxr-xr-x 2 vscode vscode 6 Jul 25 12:00 logs\\r\\n-rw-r--r-- 1 vscode vscode 0 Jul 25 12:00 notes.txt\\r\\ndrwxr-xr-x 2 vscode vscode 6 Jul 25 12:00 scripts<\\/code><\\/pre><p>Точные даты, время, размеры, владельцы и имена пользователя могут отличаться.<\\/p><p>Главное отличие от обычного ls — теперь перед именем элемента отображается дополнительная информация.<\\/p><p>&nbsp;<\\/p><p>Синтаксис для конкретного каталога:<\\/p><p><code>ls -l documents<\\/code><\\/p><p>&nbsp;<\\/p><p>Что означает подробный вывод<\\/p><p>Рассмотрим одну строку:<\\/p><p><code>-rw-r--r-- 1 vscode vscode 0 Jul 25 12:00 README.md<\\/code><\\/p><p>Первый символ показывает тип элемента.<\\/p><p>Символ - означает обычный файл.<\\/p><p>Символ d означает каталог.<\\/p><p>Например:<\\/p><p><code>drwxr-xr-x 2 vscode vscode 6 Jul 25 12:00 documents<\\/code><\\/p><p>Здесь первый символ d, поэтому documents является каталогом.<\\/p><p>Далее отображаются права доступа.<\\/p><p>В этой лекции подробно разбирать права не будем. Это отдельная тема будущей части курса.<\\/p><p>После прав отображается число ссылок, затем владелец и группа, размер, дата изменения и имя элемента.<\\/p><p>Для этой лекции главное научиться быстро различать обычные файлы и каталоги и понимать, что -l добавляет подробную информацию.<\\/p><p>&nbsp;<\\/p><p><strong>Опция -a<\\/strong><\\/p><p>Что делает опция<\\/p><p>Опция -a означает all — «все».<\\/p><p>Она заставляет ls показывать также скрытые элементы.<\\/p><p>В Linux скрытыми обычно считаются имена, начинающиеся с точки:<\\/p><p><code>.env<\\/code><\\/p><p><code>.hidden<\\/code><\\/p><p>В нашей структуре такие файлы существуют, но обычная команда ls их не показывает.<\\/p><p>Выполним:<\\/p><p><code>ls -a<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><p><code>.&nbsp; ..&nbsp; .env&nbsp; .hidden&nbsp; README.md&nbsp; config.conf&nbsp; documents&nbsp; logs&nbsp; notes.txt&nbsp; scripts<\\/code><\\/p><p>Теперь появились .env и .hidden.<\\/p><p>Но появились также . и .. (точка и двоеточие).<\\/p><p>Что такое . и ..<\\/p><p>. означает текущий каталог.<\\/p><p>.. означает родительский каталог, то есть каталог, в котором находится текущий каталог.<\\/p><p>Например, сейчас мы находимся здесь:<\\/p><p><code>...\\/lesson4<\\/code><\\/p><p>Тогда:<\\/p><p><code>.<\\/code><\\/p><p>означает lesson4 ,<\\/p><p>но:<\\/p><p><code>..<\\/code><\\/p><p>означает каталог, содержащий lesson4.<\\/p><p>Эти специальные элементы существуют в каталогах Linux и отображаются при использовании ls -a.<\\/p><p>&nbsp;<\\/p><p>Можно также указать конкретный каталог:<\\/p><p><code>ls -a documents<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике<\\/p><p>ls -a особенно полезна при диагностике проектов.<\\/p><p>В Linux и программных проектах часто существуют скрытые файлы настроек.<\\/p><p>Например:<\\/p><p><code>.env<\\/code><\\/p><p><code>.gitignore<\\/code><\\/p><p>Обычный ls их не покажет.<\\/p><p>Если разработчик говорит, что в каталоге есть файл, но ls его не показывает, одной из первых проверок будет: ls -a<\\/p><p>&nbsp;<\\/p><p><strong>Опция -la<\\/strong><\\/p><p>На практике часто требуется одновременно видеть скрытые элементы и получать подробную информацию.<\\/p><p>Для этого используется:<\\/p><p><code>ls -la<\\/code><\\/p><p>Здесь объединены две опции:<\\/p><p><code>-l<\\/code><\\/p><p><code>-a<\\/code><\\/p><p>То есть: ls -la означает: показать содержимое в подробном формате и не скрывать элементы, начинающиеся с точки.<\\/p><p>&nbsp;<\\/p><p>Можно использовать и раздельную запись:<\\/p><p><code>ls -l -a<\\/code><\\/p><p>Для ls эти варианты дают один и тот же результат.<\\/p><p>&nbsp;<\\/p><p>Выполните:<\\/p><p><code>ls -la<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><pre><code class=\\\"language-plaintext\\\">total 8\\r\\ndrwxr-xr-x 5 vscode vscode 4096 Jul 25 12:00 .\\r\\ndrwxr-xr-x 1 vscode vscode 4096 Jul 25 12:00 ..\\r\\n-rw-r--r-- 1 vscode vscode&nbsp;&nbsp;&nbsp; 0 Jul 25 12:00 .env\\r\\n-rw-r--r-- 1 vscode vscode&nbsp;&nbsp;&nbsp; 0 Jul 25 12:00 .hidden\\r\\n-rw-r--r-- 1 vscode vscode&nbsp;&nbsp;&nbsp; 0 Jul 25 12:00 README.md\\r\\n-rw-r--r-- 1 vscode vscode&nbsp;&nbsp;&nbsp; 0 Jul 25 12:00 config.conf\\r\\ndrwxr-xr-x 2 vscode vscode&nbsp;&nbsp;&nbsp; 6 Jul 25 12:00 documents\\r\\ndrwxr-xr-x 2 vscode vscode&nbsp;&nbsp;&nbsp; 6 Jul 25 12:00 logs\\r\\n-rw-r--r-- 1 vscode vscode&nbsp;&nbsp;&nbsp; 0 Jul 25 12:00 notes.txt\\r\\ndrwxr-xr-x 2 vscode vscode&nbsp;&nbsp;&nbsp; 6 Jul 25 12:00 scripts<\\/code><\\/pre><p>Точные значения зависят от конкретного Codespace.<\\/p><p>В этом выводе одновременно видны:<\\/p><p>- обычные файлы<\\/p><p>- скрытые файлы<\\/p><p>- каталоги<\\/p><p>- подробная информация<\\/p><p>- специальные элементы . и ..<\\/p><p>Именно поэтому ls -la является одной из самых полезных форм команды ls при работе в Linux.<\\/p><p>&nbsp;<\\/p><p>Практический пример<\\/p><p>Проверим содержимое домашнего каталога:<\\/p><p><code>cd ..<\\/code><\\/p><p><code>ls -la<\\/code><\\/p><p>Здесь cd .. используется потому, что мы находимся в lesson4, а домашний каталог или каталог проекта находится выше по структуре. Точный вывод зависит от структуры конкретного Codespace.<\\/p><p>После просмотра можно вернуться в учебный каталог:<\\/p><p><code>cd lesson4<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Скрытые файлы<\\/strong><\\/p><p>В Linux имя файла или каталога, начинающееся с точки, считается скрытым.<\\/p><p>Например:<\\/p><p><code>.env<\\/code><\\/p><p><code>.hidden<\\/code><\\/p><p><code>.gitignore<\\/code><\\/p><p>Это не специальный отдельный тип файла.<\\/p><p>Скрытый файл остаётся обычным файлом, но стандартная команда ls не показывает его.<\\/p><p>Это важно при работе с программными проектами.<\\/p><p>Например, Git использует скрытый каталог:<\\/p><p><code>.git<\\/code><\\/p><p>Конфигурация приложения может храниться в:<\\/p><p><code>.env<\\/code><\\/p><p>Настройки игнорирования файлов для Git часто находятся в:<\\/p><p><code>.gitignore<\\/code><\\/p><p>Если такие элементы не отображаются, это не значит, что их нет.<\\/p><p>&nbsp;<\\/p><p><strong>Структура домашнего каталога<\\/strong><\\/p><p>В Linux у каждого пользователя есть домашний каталог.<\\/p><p>Это основное место, предназначенное для хранения пользовательских файлов и каталогов.<\\/p><p>В GitHub Codespaces домашний каталог находится внутри Linux-среды Codespace.<\\/p><p>Перейти в домашний каталог из любого места (где бы вы сейчас не находились в файловой структуре) можно командой :<\\/p><p><code>cd ~<\\/code><\\/p><p>(знак ~ (тильда) всегда обозначает домашний каталог)<\\/p><p>Перейдите в домашний каталог и убедитесь в этом командой pwd.<\\/p><p>&nbsp;<\\/p><p>Выведите содержимое домашнего каталога (полную подробную информацию, включая скрытые элементы) командой<\\/p><p><code>ls -la<\\/code><\\/p><p>В реальном Codespace структура может выглядеть примерно так:<\\/p><pre><code class=\\\"language-plaintext\\\">drwxr-xr-x 2 root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096 Mar 11 12:20 .hugo\\r\\ndrwxrwxr-x 2 codespace codespace 4096 Mar 11 12:20 .jupyter\\r\\ndrwxrwxr-x 1 codespace codespace 4096 Mar 11 12:20 .local\\r\\ndrwxr-xr-x 2 root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096 Mar 11 12:20 .maven\\r\\ndrwxr-xr-x 2 codespace root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096 Apr&nbsp; 6 00:22 .minikube\\r\\ndrwxr-xr-x 2 root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; root&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096 Mar 11 12:03 .nvs\\r\\ndrwxr-xr-x 1 codespace codespace 4096 Apr&nbsp; 6 00:22 .oh-my-zsh\\r\\n. . . <\\/code><\\/pre><p>Конкретный набор файлов зависит от образа Linux, настроек Codespace и содержимого репозитория.<\\/p><p>&nbsp;<\\/p><p>Важно запомнить принцип: домашний каталог пользователя и каталог проекта — не обязательно одно и то же место.<\\/p><p>&nbsp;<\\/p><p>pwd отвечает на вопрос «Где я сейчас нахожусь?».<\\/p><p>ls отвечает на вопрос «Что находится здесь?».<\\/p><p>ls -a отвечает на вопрос «Что находится здесь, включая скрытые элементы?».<\\/p><p>ls -l отвечает на вопрос «Какая подробная информация есть об элементах здесь?».<\\/p><p>ls -la объединяет последние два варианта.<\\/p><p>Это четыре формы ls, которые необходимо уверенно различать.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Путать <code>.<\\/code> и <code>..<\\/code> .&nbsp;<\\/p><p>Точка означает текущий каталог, .. две точки — родительский каталог.<\\/p><p>- Считать скрытые файлы ненужными. Среди них могут находиться важные настройки проекта и инструментов разработки.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Для обычного быстрого просмотра используйте ls.<\\/p><p>- Если нужно проверить скрытые файлы, используйте ls -a.<\\/p><p>- Если важны свойства элементов, используйте ls -l.<\\/p><p>- При диагностике структуры каталога часто удобно сразу использовать ls -la.<\\/p>\",\"tests\":[{\"question\":\"Что произойдёт после выполнения ls -a?\",\"answers\":[\"Будут показаны только каталоги\",\"Будут удалены скрытые файлы\",\"Будут показаны также скрытые элементы\",\"Будет показана подробная информация\"],\"correct\":2},{\"question\":\"Что означает опция -l у команды ls?\",\"answers\":[\"Показывает только файлы с большими именами\",\"Включает подробный формат вывода\",\"Переходит в домашний каталог\",\"Показывает только скрытые элементы\"],\"correct\":1},{\"question\":\"Почему файл .env обычно не отображается после ls?\",\"answers\":[\"Потому что Linux не поддерживает такие файлы\",\"Потому что файл обязательно повреждён\",\"Потому что ls по умолчанию скрывает имена, начинающиеся с точки\",\"Потому что .env является каталогом\"],\"correct\":2},{\"question\":\"Что обозначает . (точка) в выводе ls -a?\",\"answers\":[\"Корневой каталог Linux\",\"Текущий каталог\",\"Домашний каталог пользователя\",\"Скрытый файл\"],\"correct\":1},{\"question\":\"Что обозначает .. (две точки) ?\",\"answers\":[\"Родительский каталог\",\"Двойной скрытый файл\",\"Текущий каталог\",\"Корневой каталог\"],\"correct\":0},{\"question\":\"Какой командой одновременно посмотреть скрытые элементы и подробную информацию?\",\"answers\":[\"ls -a\",\"ls -l\",\"ls -la\",\"ls\"],\"correct\":2},{\"question\":\"Что показывает первый символ d в строке подробного вывода ls -l?\",\"answers\":[\"Файл является скрытым\",\"Файл был удалён\",\"Элемент является каталогом\",\"Элемент принадлежит Git\"],\"correct\":2},{\"question\":\"Какой вариант эквивалентен ls -la?\",\"answers\":[\"ls -a -l\",\"ls-a-l\",\"la -ls\",\"ls la\"],\"correct\":0}],\"tasks\":[{\"task\":\"Используя ls с указанием имени каталога, отдельно просмотрите содержимое documents, scripts и logs. Определите, какие из этих каталогов содержат пользовательские файлы.\"},{\"task\":\"С помощью ls -la исследуйте каталог проекта GitHub Codespaces. Найдите скрытые элементы и определите, какие из них являются каталогами, а какие обычными файлами.\"},{\"task\":\"Перейдите из lesson4 в родительский каталог и исследуйте его содержимое с помощью ls -la. Затем вернитесь в lesson4. Во время выполнения задания контролируйте своё положение с помощью pwd.\"}]}', 1),
(9, 'Получение справки', 'get-help', 5, '{\"theory\":\"<p>В этой лекции научимся самостоятельно получать информацию о командах Linux, не запоминая все параметры и синтаксис наизусть.<\\/p><p>Основные команды и возможности:<\\/p><p><code>history<\\/code><\\/p><p><code>man<\\/code><\\/p><p><code>--help<\\/code><\\/p><p>Также разберём навигацию по страницам man, поиск внутри документации и поиск команд в истории с помощью Ctrl+R.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды GitHub Codespaces<\\/strong><\\/p><p>Откройте терминал GitHub Codespaces.<\\/p><p>Для этой лекции специальную структуру каталогов создавать не требуется. Мы будем работать с уже изученными командами и встроенной документацией Linux.<\\/p><p>Проверьте, что терминал работает:<\\/p><p><code>pwd<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><p><code>\\/workspaces\\/название-репозитория<\\/code><\\/p><p>Точный путь у вас может отличаться.<\\/p><p>Теперь выполните несколько уже знакомых команд:<\\/p><p><code>whoami<\\/code><\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>codespace<\\/code><\\/p><p>и список файлов и каталогов текущего каталога.<\\/p><p>Эти команды создадут историю команд.<\\/p><p>&nbsp;<\\/p><p><strong>История команд: history<\\/strong><\\/p><p>Команда history показывает команды, которые ранее выполнялись в текущей командной оболочке Bash.<\\/p><p>Это очень полезная возможность. Например, вы несколько минут назад выполнили длинную команду, а теперь хотите повторить её. Не обязательно вводить всё заново.<\\/p><p>Можно посмотреть историю и найти нужную команду.<\\/p><p>Синтаксис:<\\/p><p><code>history<\\/code><\\/p><p>Также можно указать количество последних команд:<\\/p><p><code>history 10<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>История особенно полезна, когда:<\\/p><p>- Нужно повторить недавно выполненную команду.<\\/p><p>- Нужно посмотреть, какие команды выполнялись в терминале.<\\/p><p>- Нужно найти ранее использованную команду.<\\/p><p>- Нужно проверить последовательность действий при диагностике проблемы.<\\/p><p>&nbsp;<\\/p><p>Пример. Выполните:<\\/p><p><code>history<\\/code><\\/p><p>Ожидаемый вывод будет примерно таким:<\\/p><p><code>&nbsp; 1&nbsp; pwd<\\/code><\\/p><p><code>&nbsp; 2&nbsp; whoami<\\/code><\\/p><p><code>&nbsp; 3&nbsp; ls<\\/code><\\/p><p><code>&nbsp; 4&nbsp; history<\\/code><\\/p><p>Номера зависят от того, сколько команд вы уже выполняли.<\\/p><p>&nbsp;<\\/p><p>Пример. История вместе с уже изученными командами<\\/p><p>Выполните:<\\/p><pre><code class=\\\"language-plaintext\\\">pwd\\r\\nwhoami\\r\\nls\\r\\nhistory 5<\\/code><\\/pre><p>Ожидаемый вывод последних строк будет похож на:<\\/p><p><code>&nbsp; 8&nbsp; pwd<\\/code><\\/p><p><code>&nbsp; 9&nbsp; whoami<\\/code><\\/p><p><code>&nbsp;10&nbsp; ls<\\/code><\\/p><p><code>&nbsp;11&nbsp; history 5<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Поиск по истории с Ctrl+R<\\/strong><\\/p><p>В Bash есть ещё более удобный способ поиска.<\\/p><p>Нажмите:<\\/p><p><code>Ctrl+R<\\/code><\\/p><p>В терминале появится приглашение поиска, например:<\\/p><p><code>(reverse-i-search)`\':<\\/code><\\/p><p>Начните вводить часть ранее использованной команды. Например:<\\/p><p><code>pwd<\\/code><\\/p><p>Bash найдёт последнюю команду, в которой встречается pwd.<\\/p><p>Это называется обратным поиском по истории.<\\/p><p>Если найденная команда подходит, нажмите Enter, чтобы выполнить её.<\\/p><p>Если хотите сначала вернуть её в командную строку и при необходимости изменить, используйте клавишу →.<\\/p><p>&nbsp;<\\/p><p>Почему Ctrl+R особенно полезен ?<\\/p><p>Представьте, что несколько минут назад вы выполнили длинную команду:<\\/p><p>какая-то длинная команда с множеством параметров<\\/p><p>Запоминать её необязательно. Нажмите Ctrl+R и начните вводить уникальную часть команды.<\\/p><p>В реальной работе системного администратора, разработчика или DevOps-инженера такой способ поиска используется постоянно.<\\/p><p>&nbsp;<\\/p><p><strong>Получение справки с помощью --help<\\/strong><\\/p><p>Многие команды Linux поддерживают параметр --help.<\\/p><p>Он позволяет быстро получить краткую встроенную справку о команде (конечно, на английском языке).<\\/p><p>Например:<\\/p><p><code>ls --help<\\/code><\\/p><p>Команда ls запускается с параметром --help и вместо обычного списка файлов показывает информацию о доступных параметрах.<\\/p><p>&nbsp;<\\/p><p>Для этого курса достаточно запомнить --help без параметров:<\\/p><p><code>команда --help<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>- help удобно использовать, когда:<\\/p><p>- Нужно быстро вспомнить синтаксис команды.<\\/p><p>- Нужно узнать основные параметры.<\\/p><p>- Нужно посмотреть, какие аргументы принимает программа.<\\/p><p>- Не хочется открывать длинную страницу документации.<\\/p><p>&nbsp;<\\/p><p>Пример. Справка для pwd<\\/p><p><code>pwd --help<\\/code><\\/p><p>Ожидаемый вывод содержит краткое описание команды и её параметров.<\\/p><p>&nbsp;<\\/p><p>Пример. Справка для history<\\/p><p><code>history --help<\\/code><\\/p><p>В зависимости от реализации Bash вы получите информацию о синтаксисе и возможностях встроенной команды.<\\/p><p>&nbsp;<\\/p><p>--help обычно даёт краткую справку.<\\/p><p>Если требуется подробное описание команды, обычно используют man.<\\/p><p>&nbsp;<\\/p><p><strong>Документация man<\\/strong><\\/p><p>man означает manual — руководство.<\\/p><p>Это одна из важнейших систем встроенной документации Linux.<\\/p><p>Вместо того чтобы искать информацию в интернете, во многих случаях можно обратиться непосредственно к документации, установленной в системе.<\\/p><p>&nbsp;<\\/p><p>Команда man открывает страницу руководства для указанной команды.<\\/p><p>Например:<\\/p><p><code>man ls<\\/code><\\/p><p>Откроется подробная документация по команде ls.<\\/p><p>&nbsp;<\\/p><p>Например:<\\/p><p><code>man pwd<\\/code><\\/p><p>или:<\\/p><p><code>man history<\\/code><\\/p><p>&nbsp;<\\/p><p>На начальном этапе основное использование:<\\/p><p><code>man команда<\\/code><\\/p><p>Дополнительные возможности man существуют, но сейчас изучать их подробно не требуется.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике?<\\/p><p>man используется, когда:<\\/p><p>- Нужно подробно разобраться в команде.<\\/p><p>- Нужно узнать все основные параметры.<\\/p><p>- Нужно понять точный синтаксис.<\\/p><p>- Нужно уточнить значение конкретной опции.<\\/p><p>- Нужно посмотреть официальную документацию, установленную вместе с Linux.<\\/p><p>&nbsp;<\\/p><p>Если отдельная страница man для команды недоступна, система может сообщить, что документация не найдена. Это нормально: не каждая встроенная команда Bash обязательно представлена отдельной страницей man.<\\/p><p>В таких случаях используйте:<\\/p><p><code>команда --help<\\/code><\\/p><p>&nbsp;<\\/p><p>Навигация по страницам man<\\/p><p>Страница man обычно открывается не как обычный текстовый файл, а через специальный просмотрщик.<\\/p><p>Главное, что нужно научиться делать:<\\/p><p>- перемещаться вверх и вниз<\\/p><p>- искать текст<\\/p><p>- выходить из документации<\\/p><p>&nbsp;<\\/p><p>Перемещение вниз :<\\/p><p>Нажмите: <code>Space<\\/code><\\/p><p>Покажется следующая страница.<\\/p><p>Также можно нажимать: <code>Enter<\\/code><\\/p><p>Чтобы двигаться вниз построчно.<\\/p><p>Клавиша: <code>↓<\\/code> тоже позволяет двигаться вниз.<\\/p><p>&nbsp;<\\/p><p>Перемещение вверх :<\\/p><p>Используйте: <code>↑<\\/code> или: <code>b<\\/code><\\/p><p>Клавиша b перемещает назад на страницу.<\\/p><p>&nbsp;<\\/p><p>Выход :<\\/p><p>Для выхода из man нажмите: <code>q<\\/code><\\/p><p>После этого вы вернётесь в обычный терминал.<\\/p><p>&nbsp;<\\/p><p>Практика :<\\/p><p>Откройте:&nbsp;<\\/p><p><code>man ls<\\/code><\\/p><p>Попробуйте: <code>Space&nbsp;<\\/code><\\/p><p>Затем: <code>b<\\/code><\\/p><p>После этого выйдите: <code>q<\\/code><\\/p><p>&nbsp;<\\/p><p>Поиск внутри man<\\/p><p>Большая страница документации может содержать очень много информации.<\\/p><p>Читать её целиком обычно не требуется.<\\/p><p>Гораздо эффективнее найти нужное слово.<\\/p><p>Поиск вперёд :<\\/p><p>Внутри man нажмите: <code>\\/<\\/code><\\/p><p>После этого введите поисковый запрос.<\\/p><p>Например: <code>\\/hidden<\\/code> и нажмите: <code>Enter<\\/code><\\/p><p>Просмотрщик найдёт первое совпадение.<\\/p><p>Для перехода к следующему совпадению нажмите: <code>n<\\/code><\\/p><p>Для предыдущего совпадения: <code>N<\\/code><\\/p><p>&nbsp;<\\/p><p>Почему поиск важнее чтения всей страницы ?<\\/p><p>В реальной работе редко требуется прочитать весь man.<\\/p><p>Например, вам нужно вспомнить, какой параметр ls показывает скрытые файлы.<\\/p><p>Вместо чтения всей документации можно выполнить: <code>man ls<\\/code> затем: <code>\\/hidden<\\/code> и быстро найти нужный раздел.<\\/p><p>Это один из основных навыков работы с Linux-документацией.<\\/p><p>&nbsp;<\\/p><p><strong>Как выбирать между history, --help и man<\\/strong><\\/p><p>Эти три возможности решают разные задачи.<\\/p><p>Практический алгоритм можно запомнить так:<\\/p><p>Если я уже выполнял эту команду — использую history или Ctrl+R.<\\/p><p>Если мне нужно быстро вспомнить параметры — использую --help.<\\/p><p>Если нужно подробно разобраться в команде — использую man.<\\/p><p>&nbsp;<\\/p><p><strong>Встроенная документация Linux<\\/strong><\\/p><p>Одна из важных особенностей Linux — большое количество информации доступно непосредственно в самой системе.<\\/p><p>Так постепенно формируется важный навык Linux-пользователя: не запоминать всё, а уметь быстро найти нужную информацию.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Пытаться запомнить все параметры каждой команды вместо использования документации.<\\/p><p>- Читать всю страницу man целиком, когда требуется только один конкретный параметр.<\\/p><p>- Игнорировать Ctrl+R и заново набирать длинные команды.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Сначала использовать --help, если нужна быстрая информация о команде.<\\/p><p>- Использовать man, когда требуется подробное описание.<\\/p><p>- В больших страницах man сразу применять поиск через \\/.<\\/p><p>- Для повторного использования старых команд применять Ctrl+R.<\\/p><p>- Воспринимать документацию Linux как рабочий инструмент, а не как справочник, который нужно прочитать целиком.<\\/p>\",\"tests\":[{\"question\":\"Что показывает команда history?\",\"answers\":[\"Список файлов текущего каталога\",\"Историю выполненных команд\",\"Историю операционной системы Linux\",\"Содержимое системной документации\"],\"correct\":1},{\"question\":\"Как открыть руководство по команде ls?\",\"answers\":[\"man ls\",\"ls man\",\"history ls\",\"ls --manual\"],\"correct\":0},{\"question\":\"Какая клавиша обычно используется для выхода из страницы man?\",\"answers\":[\"Enter\",\"Esc\",\"q\",\"Ctrl+R\"],\"correct\":2},{\"question\":\"Как начать поиск текста внутри страницы man?\",\"answers\":[\"Нажать \\/ и ввести поисковый запрос\",\"Нажать q и ввести поисковый запрос\",\"Нажать Ctrl+R\",\"Нажать Space, затем Enter\"],\"correct\":0},{\"question\":\"Что делает сочетание Ctrl+R в Bash?\",\"answers\":[\"Удаляет текущую команду\",\"Очищает экран терминала\",\"Запускает страницу man\",\"Ищет ранее выполненную команду в истории\"],\"correct\":3},{\"question\":\"Что обычно предоставляет man?\",\"answers\":[\"Краткую помощь по команде\",\"Подробное руководство по команде\",\"Список файлов текущего каталога\",\"Историю команд пользователя\"],\"correct\":1}],\"tasks\":[{\"task\":\"Откройте справку по команде ls с помощью ls --help и найдите в выводе информацию о параметрах -a и -l.\"},{\"task\":\"Откройте man ls и с помощью поиска внутри документации найдите информацию о скрытых файлах.\"}]}', 1),
(10, 'Просмотр текстовых файлов', 'browse-text-files', 6, '{\"theory\":\"<p>В этой лекции научимся читать содержимое текстовых файлов прямо из терминала GitHub Codespaces.&nbsp;<\\/p><p>Для этого разберём четыре команды: cat, less, head и tail.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды GitHub Codespaces<\\/strong><\\/p><p>Для этой лекции не нужно создавать дополнительные файлы: в Linux уже есть системные текстовые файлы, которые можно безопасно просматривать. Это позволяет изучать команды без использования touch, mkdir, echo и перенаправления вывода, которые появятся в следующих лекциях.<\\/p><p>Откройте терминал GitHub Codespaces и &nbsp;перейдите в домашний каталог:<\\/p><p><code>cd ~<\\/code><\\/p><p>Проверьте, где вы находитесь:<\\/p><p><code>pwd<\\/code><\\/p><p>Вывод будет похож на:<\\/p><p><code>\\/home\\/codespace<\\/code><\\/p><p>Для практики будем использовать системные текстовые файлы:<\\/p><p><code>\\/etc\\/os-release<\\/code><\\/p><p><code>\\/etc\\/hosts<\\/code><\\/p><p><code>\\/etc\\/services<\\/code><\\/p><p>Они содержат обычный текст и доступны для чтения.<\\/p><p>Проверить их наличие можно уже знакомой командой:<\\/p><p><code>ls -l \\/etc\\/os-release \\/etc\\/hosts \\/etc\\/services<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><p><code>-rw-r--r-- 1 root root ... \\/etc\\/hosts<\\/code><\\/p><p><code>-rw-r--r-- 1 root root ... \\/etc\\/os-release<\\/code><\\/p><p><code>-rw-r--r-- 1 root root ... \\/etc\\/services<\\/code><\\/p><p>Числа и некоторые сведения могут отличаться в конкретном Codespace.<\\/p><p>&nbsp;<\\/p><p><strong>Команда cat<\\/strong><\\/p><p>cat выводит содержимое текстового файла непосредственно в терминал.<\\/p><p>Название команды происходит от английского слова concatenate — «объединять». Исторически команда предназначена не только для просмотра, но и для последовательного вывода содержимого нескольких файлов.<\\/p><p>На начальном этапе нам, прежде всего, важно использовать cat именно для быстрого просмотра небольших текстовых файлов.<\\/p><p>Синтаксис:<\\/p><p><code>cat имя_файла<\\/code><\\/p><p>Например:<\\/p><p><code>cat \\/etc\\/os-release<\\/code><\\/p><p>Команда прочитает файл \\/etc\\/os-release и выведет его содержимое в терминал.<\\/p><p>Ожидаемый вывод будет примерно таким:<\\/p><p><span class=\\\"text-tiny\\\"><code>PRETTY_NAME=\\\"Ubuntu ...\\\"<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>NAME=\\\"Ubuntu\\\"<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>VERSION_ID=\\\"...\\\"<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>VERSION=\\\"...\\\"<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>VERSION_CODENAME=...<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>ID=ubuntu<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>ID_LIKE=debian<\\/code><\\/span><\\/p><p><span class=\\\"text-tiny\\\"><code>...<\\/code><\\/span><\\/p><p>Точное содержимое зависит от версии Linux, используемой в Codespace.<\\/p><p>&nbsp;<\\/p><p>Дополнительные параметры cat пока подробно не рассматриваем.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>cat особенно удобна, когда файл небольшой и его содержимое помещается на экране.<\\/p><p>Например, разработчик может быстро проверить конфигурационный файл, посмотреть небольшой текстовый документ или убедиться, какие параметры записаны в системном файле.<\\/p><p>&nbsp;<\\/p><p>Практический пример. Просмотр файла с несколькими строками<\\/p><p><code>cat \\/etc\\/hosts<\\/code><\\/p><p>Ожидаемый вывод будет похож на:<\\/p><p><code>127.0.0.1 localhost<\\/code><\\/p><p><code>127.0.1.1 codespace<\\/code><\\/p><p><code>...<\\/code><\\/p><p>Конкретные строки зависят от окружения.<\\/p><p>&nbsp;<\\/p><p>Важное ограничение cat<\\/p><p>Если файл очень большой, cat может оказаться неудобной.<\\/p><p>Например:<\\/p><p><code>cat \\/etc\\/services<\\/code><\\/p><p>Вывод может быть настолько длинным, что первые строки быстро исчезнут вверх за пределами экрана.<\\/p><p>Для больших файлов лучше использовать less.<\\/p><p>&nbsp;<\\/p><p><strong>Команда less<\\/strong><\\/p><p>less позволяет просматривать текстовый файл постранично.<\\/p><p>В отличие от cat, команда не пытается показать весь файл сразу. Она открывает файл в специальном режиме просмотра, где можно перемещаться вверх и вниз, искать текст и выйти обратно в терминал.<\\/p><p>Это одна из самых полезных команд для работы с большими текстовыми файлами.<\\/p><p>Синтаксис :<\\/p><p><code>less имя_файла<\\/code><\\/p><p>Например:<\\/p><p><code>less \\/etc\\/services<\\/code><\\/p><p>После выполнения команды содержимое файла откроется в режиме просмотра.<\\/p><p>&nbsp;<\\/p><p>Навигация внутри less<\\/p><p>Для движения по файлу используются клавиши клавиатуры.<\\/p><p>Стрелка вниз — перейти ниже.<\\/p><p>Стрелка вверх — перейти выше.<\\/p><p>Space — перейти на следующую страницу.<\\/p><p>b — вернуться на предыдущую страницу.<\\/p><p>g — перейти в начало файла.<\\/p><p>G — перейти в конец файла.<\\/p><p>q — выйти из less.<\\/p><p>Это особенно важно запомнить:&nbsp;<\\/p><p>Чтобы закончить просмотр и вернуться к обычному приглашению Bash, нажмите q.<\\/p><p>&nbsp;<\\/p><p>Поиск внутри файла:<\\/p><p>Внутри less можно искать текст.<\\/p><p>Нажмите \\/, затем введите искомое слово.<\\/p><p>Например, откройте:<\\/p><p><code>less \\/etc\\/services<\\/code><\\/p><p>Затем нажмите: <code>\\/<\\/code><\\/p><p>Введите: <code>http<\\/code><\\/p><p>и нажмите Enter.<\\/p><p>less найдёт совпадение.<\\/p><p>&nbsp;<\\/p><p>Для перехода к следующему найденному совпадению используется: <code>n<\\/code><\\/p><p>Для выхода: <code>q<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>less используется, когда файл слишком большой для удобного просмотра через cat.<\\/p><p>Например, с его помощью удобно просматривать логи, конфигурационные файлы, документацию и большие текстовые данные.<\\/p><p>&nbsp;<\\/p><p><strong>Команда head<\\/strong><\\/p><p>head выводит начало текстового файла.<\\/p><p>По умолчанию команда показывает первые 10 строк.<\\/p><p>Это удобно, когда файл большой, а нужно быстро посмотреть только его начало.<\\/p><p>Синтаксис :<\\/p><p><code>head имя_файла<\\/code><\\/p><p>&nbsp;<\\/p><p>Часто используется параметр:<\\/p><p><code>-n число<\\/code><\\/p><p>Он задаёт количество выводимых строк.<\\/p><p>Например:<\\/p><p><code>head -n 5 \\/etc\\/services<\\/code><\\/p><p>покажет первые 5 строк.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>head полезна для быстрой проверки структуры большого файла.<\\/p><p>Например, перед обработкой данных можно посмотреть первые несколько строк и понять, действительно ли это тот файл, который нужен.<\\/p><p>Также команда часто используется при диагностике и работе с логами.<\\/p><p>&nbsp;<\\/p><p><strong>Команда tail<\\/strong><\\/p><p>tail выводит конец текстового файла.<\\/p><p>По умолчанию команда показывает последние 10 строк.<\\/p><p>Это особенно полезно при работе с логами, потому что самые свежие записи часто находятся в конце файла.<\\/p><p>Синтаксис :<\\/p><p><code>tail имя_файла<\\/code><\\/p><p>Как и у head, можно указать количество строк:<\\/p><p><code>-n число<\\/code><\\/p><p>Например:<\\/p><p><code>tail -n 5 \\/etc\\/services<\\/code><\\/p><p>покажет последние 5 строк.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>tail часто применяется при диагностике программ и серверов.<\\/p><p>Если приложение записывает события в лог-файл, последние строки могут содержать самую свежую информацию об ошибках или действиях программы.<\\/p><p>&nbsp;<\\/p><p>В реальной работе можно встретить конструкции вроде:<\\/p><p><code>tail -n 20 файл.log<\\/code><\\/p><p>Они позволяют быстро посмотреть последние 20 строк большого журнала.<\\/p><p>&nbsp;<\\/p><p>Практический пример. Последние строки системного файла<\\/p><p><code>tail -n 3 \\/etc\\/os-release<\\/code><\\/p><p>Команда покажет последние три строки файла.<\\/p><p>Точный вывод зависит от версии Ubuntu.<\\/p><p>&nbsp;<\\/p><p><strong>Как выбрать команду ?<\\/strong><\\/p><p>Запомнить назначение команд можно следующим образом:<\\/p><p><code>cat<\\/code> - Быстро показать содержимое небольшого файла целиком.<\\/p><p><code>less<\\/code> - Удобно просматривать большой файл и перемещаться по нему.<\\/p><p><code>head<\\/code> - Посмотреть начало файла.<\\/p><p><code>tail<\\/code> - Посмотреть конец файла.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Использовать cat для огромных файлов, когда вывод полностью заполняет терминал и становится неудобным для просмотра.<\\/p><p>- Забывать, что less работает в отдельном режиме и для выхода из него нужно нажать q.<\\/p><p>- Не проверять начало файла перед дальнейшей работой с неизвестными данными.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Для небольших файлов использовать cat, когда весь текст удобно увидеть сразу.<\\/p><p>- Для больших файлов использовать less и перемещаться по содержимому постепенно.<\\/p>\",\"tests\":[{\"question\":\"Какую задачу выполняет команда cat?\",\"answers\":[\"Переходит в другой каталог\",\"Выводит содержимое текстового файла\",\"Показывает только последние строки файла\",\"Открывает справочную страницу команды\"],\"correct\":1},{\"question\":\"Какая команда предназначена для постраничного просмотра большого текстового файла?\",\"answers\":[\"head\",\"cat\",\"tail\",\"less\"],\"correct\":3},{\"question\":\"Что по умолчанию показывает команда head?\",\"answers\":[\"Первые 10 строк файла\",\"Последние 10 строк файла\",\"Весь файл без остановки\",\"Только первую строку файла\"],\"correct\":0},{\"question\":\"Что по умолчанию показывает команда tail?\",\"answers\":[\"Первые 5 строк\",\"Последнюю строку\",\"Последние 10 строк файла\",\"Размер файла в байтах\"],\"correct\":2},{\"question\":\"Как выйти из режима просмотра less?\",\"answers\":[\"Нажать Enter\",\"Нажать q\",\"Нажать Ctrl+C\",\"Нажать Space\"],\"correct\":1},{\"question\":\"Какая команда покажет первые 5 строк файла?\",\"answers\":[\"head -n 5 \\/etc\\/services\",\"tail -n 5 \\/etc\\/services\",\"less -n 5 \\/etc\\/services\",\"cat -n 5 \\/etc\\/services\"],\"correct\":0},{\"question\":\"Какая команда покажет последние 5 строк файла?\",\"answers\":[\"head -n 5 \\/etc\\/services\",\"less \\/etc\\/services\",\"tail -n 5 \\/etc\\/services\",\"cat -n 5 \\/etc\\/services\"],\"correct\":2},{\"question\":\"Какая команда лучше всего подходит для поиска текста внутри большого файла?\",\"answers\":[\"head\",\"less\",\"tail\",\"pwd\"],\"correct\":1},{\"question\":\"В каком случае cat обычно удобнее less?\",\"answers\":[\"Когда файл небольшой и его содержимое удобно вывести целиком\",\"Когда файл настолько большой, что занимает тысячи экранов\",\"Когда нужно перейти в конец файла и искать ошибки\",\"Когда требуется перемещаться между страницами документа\"],\"correct\":0},{\"question\":\"Для чего на практике особенно полезна команда tail?\",\"answers\":[\"Для перехода в конец домашнего каталога\",\"Для создания новых каталогов\",\"Для просмотра только первой строки конфигурационного файла\",\"Для просмотра последних строк большого файла, например журнала\"],\"correct\":3}],\"tasks\":[{\"task\":\"Используя cat, просмотрите содержимое \\/etc\\/os-release. Найдите в выводе название операционной системы и её идентификатор.\"},{\"task\":\"Откройте \\/etc\\/services через less и найдите внутри файла информацию, связанную с ssh. Перейдите к следующему найденному совпадению.\"},{\"task\":\"Найдите, какая версия Ubuntu используется в Codespace, используя наиболее подходящую команду.\"}]}', 1),
(11, 'Основы HTTP и команда curl', 'http-curl', 7, '{\"theory\":\"<p><strong>Подготовка среды<\\/strong><\\/p><p>Перед выполнением примеров откройте терминал GitHub Codespaces.<\\/p><p>Проверьте, что команда curl установлена:<\\/p><p><code>curl --version<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>curl 8.x.x<\\/code><\\/p><p><code>Protocols: http https ...<\\/code><\\/p><p><code>Features: ...<\\/code><\\/p><p>Если информация о версии появилась, значит всё готово к работе.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое HTTP<\\/strong><\\/p><p>HTTP (HyperText Transfer Protocol) — это протокол обмена данными между клиентом и веб-сервером.<\\/p><p>Когда вы открываете сайт в браузере, происходит следующее:<\\/p><p>- Браузер отправляет HTTP-запрос.<\\/p><p>- Сервер получает запрос.<\\/p><p>- Сервер отправляет ответ.<\\/p><p>- Браузер показывает полученные данные.<\\/p><p>Команда curl позволяет выполнять такие же запросы прямо из терминала.<\\/p><p>Это очень полезно при работе с веб-сайтами, REST API, автоматизацией и Bash-сценариями.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое URL<\\/strong><\\/p><p>URL — это адрес ресурса в Интернете.<\\/p><p>Например:<\\/p><p><code>https:\\/\\/example.com<\\/code><\\/p><p>или<\\/p><p><code>https:\\/\\/example.com\\/index.html<\\/code><\\/p><p>URL обычно состоит из нескольких частей:<\\/p><p><code>https:\\/\\/example.com\\/index.html<\\/code><\\/p><p><code>&nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; │<\\/code><\\/p><p><code>&nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; └── путь к ресурсу и\\/или имя ресурса<\\/code><\\/p><p><code>&nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; └────────────── имя сервера<\\/code><\\/p><p><code>&nbsp; └─────────────────────── протокол<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Команда curl<\\/strong><\\/p><p>curl отправляет сетевые запросы и получает ответы от веб-серверов.<\\/p><p>Синтаксис :<\\/p><p><code>curl URL<\\/code><\\/p><p>Когда используется ?<\\/p><p>- Просмотр веб-страниц<\\/p><p>- Проверка доступности сайтов<\\/p><p>- Работа с REST API<\\/p><p>- Автоматизация в Bash<\\/p><p>&nbsp;<\\/p><p><strong>GET-запросы<\\/strong><\\/p><p>По умолчанию curl выполняет GET-запрос.<\\/p><p>GET используется для получения данных с сервера.<\\/p><p>Например:<\\/p><p><code>curl https:\\/\\/example.com<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>&lt;!doctype html&gt;&lt;html lang=\\\"en\\\"&gt;&lt;head&gt;&lt;title&gt;Example Domain&lt;\\/title&gt;&lt;link<\\/code><\\/p><p><code>. . .<\\/code><\\/p><p><code>Learn more&lt;\\/a&gt;&lt;\\/p&gt;&lt;\\/div&gt;&lt;\\/body&gt;&lt;\\/html&gt;<\\/code><\\/p><p>В терминал выводится HTML-код страницы.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр содержимого веб-страниц<\\/strong><\\/p><p>Можно просмотреть другую страницу.<\\/p><p><code>curl https:\\/\\/www.linux.org\\/<\\/code><\\/p><p>&nbsp;<\\/p><p>Иногда HTML очень большой.<\\/p><p>Чтобы посмотреть только начало страницы, можно использовать уже знакомую команду head.<\\/p><p><code>curl https:\\/\\/www.linux.org | head<\\/code><\\/p><p>&nbsp;<\\/p><p>Если адрес указан неверно, сервер обычно возвращает сообщение об ошибке.<\\/p><p>&nbsp;<\\/p><p><strong>Заголовки HTTP-ответа<\\/strong><\\/p><p>Когда curl обращается к веб-серверу, сервер возвращает HTTP-ответ. Он состоит не только из содержимого страницы. Сначала сервер отправляет служебную информацию — HTTP-заголовки, а затем, само содержимое.<\\/p><p>&nbsp;<\\/p><p>Параметр :<\\/p><p><code>-I<\\/code><\\/p><p>показывает только заголовки ответа:<\\/p><p><code>curl -I https:\\/\\/example.com<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>HTTP\\/2 200<\\/code><\\/p><p><code>date: Wed, 29 Jul 2026 06:51:33 GMT<\\/code><\\/p><p><code>content-type: text\\/html<\\/code><\\/p><p><code>server: cloudflare<\\/code><\\/p><p><code>last-modified: Tue, 21 Jul 2026 07:16:00 GMT<\\/code><\\/p><p><code>allow: GET, HEAD<\\/code><\\/p><p><code>accept-ranges: bytes<\\/code><\\/p><p><code>. . .<\\/code><\\/p><p>Здесь:<\\/p><p><code>HTTP\\/2<\\/code> — версия протокола.<\\/p><p><code>200<\\/code> — код ответа. Он означает, что запрос выполнен успешно.<\\/p><p><code>date: Wed, 29 Jul 2026 06:51:33 GMT<\\/code> — текущие дата и время<\\/p><p><code>content-type: text\\/html<\\/code> — тип получаемого содержимого. В данном случае сервер сообщает, что это HTML-документ.<\\/p><p>… и т.д.<\\/p><p>Заголовки нужны программе-клиенту, чтобы понять, что сервер вернул и как с этим работать.<\\/p><p>Например, браузер использует Content-Type, чтобы понять, что получен HTML-документ, а не изображение или другой тип данных.<\\/p><p>&nbsp;<\\/p><p>В случае, когда мы запускаем curl с параметром -I , выводятся только HTTP-заголовки.<\\/p><p>В этом случае curl не выводит сам HTML-код страницы.<\\/p><p>Мы получаем только служебную информацию о HTTP-ответе.<\\/p><p>В реальной работе заголовки полезны, например, когда нужно быстро проверить, отвечает ли сервер, какой тип данных он возвращает и какой код HTTP-ответа получен.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Параметр -L (Следовать перенаправлениям)<\\/strong><\\/p><p>Попробуйте следующую команду:<\\/p><p><code>curl https:\\/egov.kz<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>&lt;html&gt;<\\/code><\\/p><p><code>&lt;head&gt;&lt;title&gt;301 Moved Permanently&lt;\\/title&gt;&lt;\\/head&gt;<\\/code><\\/p><p><code>&lt;body&gt;<\\/code><\\/p><p><code>&lt;center&gt;&lt;h1&gt;301 Moved Permanently&lt;\\/h1&gt;&lt;\\/center&gt;<\\/code><\\/p><p><code>. . .<\\/code><\\/p><p>Т.е. код главной страницы данного ресурса - сайта egov.kz - не отображается, т.к. на сервере, по URL egov.kz, настроено перенаправление на другой URL (какой именно - не важно). Это сделано для безопасности.<\\/p><p>В этом случае мы можем использовать параметр -L , который заставит curl пройти по всем перенаправлениям до конечного URL, на котором находится искомый ресурс.<\\/p><p>Выполните:<\\/p><p><code>curl -L https:\\/egov.kz<\\/code><\\/p><p>и проанализируйте результат.<\\/p><p>&nbsp;<\\/p><p>Где curl используется на практике ?<\\/p><p>- Проверка работы сайта.<\\/p><p>- Проверка доступности веб-сервиса.<\\/p><p>- Получение данных из API.<\\/p><p>- Автоматизация проверки серверов.<\\/p><p>- Тестирование веб-приложений.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>Не проверять правильность URL перед отправкой запроса.<\\/p><p>Не обращать внимания на сообщения об ошибках сервера.<\\/p><p>Использовать неизвестные сайты без необходимости.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>Всегда внимательно проверяйте URL.<\\/p><p>Используйте curl для быстрой проверки работы сайта без открытия браузера.<\\/p>\",\"tests\":[{\"question\":\"Каково основное назначение протокола HTTP?\",\"answers\":[\"Передача файлов между каталогами Linux\",\"Получение и передача данных между клиентом и сервером\",\"Создание пользователей в ОС Linux\",\"Установка программ\"],\"correct\":1},{\"question\":\"Что такое URL?\",\"answers\":[\"Имя пользователя Linux\",\"Адрес ресурса в Интернете\",\"Команда Bash\",\"Название веб-сервера Linux\"],\"correct\":1},{\"question\":\"Какая команда получает содержимое веб-страницы?\",\"answers\":[\"cat https:\\/\\/example.com\",\"curl https:\\/\\/example.com\",\"content https:\\/\\/example.com\",\"ls https:\\/\\/example.com\"],\"correct\":1},{\"question\":\"Какой тип запроса выполняет curl по умолчанию?\",\"answers\":[\"POST\",\"DELETE\",\"GET\",\"PUT\"],\"correct\":2},{\"question\":\"Что обычно выводит curl <URL>?\",\"answers\":[\"Список процессов на указанном ресурсе\",\"HTML-код страницы\",\"IP-адрес компьютера\",\"Историю команд\"],\"correct\":1},{\"question\":\"Какой параметр показывает только HTTP-заголовки?\",\"answers\":[\"-a\",\"-headers\",\"-I\",\"-h\"],\"correct\":2},{\"question\":\"Для чего используется параметр -L?\",\"answers\":[\"Удаление страницы\",\"Переход по перенаправлениям\",\"Просмотр истории\",\"Вывод последних строк\"],\"correct\":1},{\"question\":\"Какая команда покажет начало HTML-документа?\",\"answers\":[\"curl https:\\/\\/example.com | head\",\"curl https:\\/\\/example.com | tail\",\"curl https:\\/\\/example.com | begin\",\"curl https:\\/\\/example.com | start\"],\"correct\":0}],\"tasks\":[{\"task\":\"Получите содержимое страницы https:\\/\\/www.gnu.org и найдите в выводе строку с тегом .\"},{\"task\":\"Используйте команду curl совместно с head, чтобы вывести только первые 15 строк страницы https:\\/\\/example.com.\"},{\"task\":\"Получите только HTTP-заголовки страницы https:\\/\\/www.gnu.org с помощью соответствующего параметра curl и определите код ответа сервера.\"}]}', 1);
INSERT INTO `lessons` (`id`, `title_ru`, `slug`, `lesson_order`, `content`, `is_published`) VALUES
(12, 'Загрузка файлов с помощью curl', 'download-by-curl', 8, '{\"theory\":\"<p>Темы лекции:<\\/p><p>- Команда curl<\\/p><p>- HTTP-заголовки<\\/p><p>- Загрузка файлов<\\/p><p>- Сохранение ответа в файл<\\/p><p>- Наиболее полезные параметры curl<\\/p><p>&nbsp;<\\/p><p><strong>Сначала, повторим, другими словами, знания из предыдущей лекции о curl<\\/strong><\\/p><p>&nbsp;<\\/p><p><strong>Что такое curl<\\/strong><\\/p><p>curl — это консольная утилита для передачи данных по сети.<\\/p><p>С помощью curl можно:<\\/p><p>- отправлять запросы на серверы в интернет (HTTP-запросы);<\\/p><p>- получать данные с серверов;<\\/p><p>- загружать файлы;<\\/p><p>- отправлять файлы на сервер;<\\/p><p>- работать с API;<\\/p><p>- просматривать HTTP-заголовки;<\\/p><p>- тестировать веб-сервисы.<\\/p><p>&nbsp;<\\/p><p>В Linux curl используется практически во всех областях:<\\/p><p>- разработка программ;<\\/p><p>- администрирование серверов;<\\/p><p>- автоматизация задач;<\\/p><p>- работа с REST API.<\\/p><p>&nbsp;<\\/p><p>Проверить наличие curl:<\\/p><p><code>curl --version<\\/code><\\/p><p>&nbsp;<\\/p><p>Если в той среде, где вы выполняете команды Linux, curl не установлен, вы можете установить его следующей командой (для Ubuntu):<\\/p><p><code>sudo apt update<\\/code><\\/p><p><code>sudo apt install curl<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Использование curl<\\/strong><\\/p><p>Общий вид команды:<\\/p><p><code>curl [параметры] URL<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример:<\\/p><p><code>curl https:\\/\\/example.com<\\/code><\\/p><p>Команда отправляет HTTP GET-запрос и выводит ответ сервера в терминал.<\\/p><p>Пример ответа:<\\/p><p><code>&lt;!doctype html&gt;&lt;html lang=\\\"en\\\"&gt;&lt;head&gt;&lt;title&gt;Example Domain&lt;\\/title&gt;&lt;link rel=\\\"icon\\\" href=\\\"data:,\\\"&gt;&lt;meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1\\\"&gt;&lt;style&gt;body{background:#eee;width:60vw;margin:15vh auto;font-family:system-ui,sans-serif}h1{font-size:1.5em}div{opacity:0.8}a:link,a:visited{color:#348}&lt;\\/style&gt;&lt;\\/head&gt;&lt;body&gt;&lt;div&gt;&lt;h1&gt;Example Domain&lt;\\/h1&gt;&lt;p&gt;This domain is for use in documentation examples without needing permission. Avoid use in operations.&lt;\\/p&gt;&lt;p&gt;&lt;a href=\\\"https:\\/\\/iana.org\\/domains\\/example\\\"&gt;Learn more&lt;\\/a&gt;&lt;\\/p&gt;&lt;\\/div&gt;&lt;\\/body&gt;&lt;\\/html&gt;<\\/code><\\/p><p>По умолчанию curl выводит полученные данные в стандартный вывод — терминал.<\\/p><p>При выполнении команды curl без параметров, команда выводит только тело HTTP-запроса (содержимое ресурса на сервере по указанному URL-адресу) (в данном случае HTML-код web-страницы).<br>Кроме тела запроса, в запросе присутствуют, также, заголовки HTTP-запроса.<\\/p><p>&nbsp;<\\/p><p><strong>HTTP-заголовки<\\/strong><\\/p><p>HTTP-заголовки — это дополнительная информация, которая передаётся вместе с запросом или ответом.<\\/p><p>Заголовки используются для передачи:<\\/p><p>- типа данных;<\\/p><p>- информации о клиенте;<\\/p><p>- авторизации;<\\/p><p>- параметров соединения.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр HTTP-заголовков ответа (<\\/strong>параметр: -I)<\\/p><p>Пример:<\\/p><p><code>curl -I https:\\/\\/example.com<\\/code><\\/p><p>Ответ может быть примерно таким:<\\/p><p><code>HTTP\\/2 200<\\/code><\\/p><p><code>date: Mon, 27 Jul 2026 06:27:03 GMT<\\/code><\\/p><p><code>content-type: text\\/html<\\/code><\\/p><p><code>server: cloudflare<\\/code><\\/p><p><code>last-modified: Mon, 20 Jul 2026 07:16:20 GMT<\\/code><\\/p><p><code>allow: GET, HEAD<\\/code><\\/p><p>Можно увидеть:<\\/p><p>Версию HTTP-протокола: <code>HTTP\\/2<\\/code><\\/p><p>код ответа: <code>200<\\/code> (т.е. успешно);<\\/p><p>дату и время: <code>Mon, 27 Jul 2026 06:27:03 GMT;<\\/code><\\/p><p>тип данных: <code>text\\/html;<\\/code><\\/p><p>сервер: <code>cloudflare;<\\/code><\\/p><p>параметры соединения и другие данные.<\\/p><p>&nbsp;<\\/p><p><strong>Полный вывод с заголовками и телом <\\/strong>(параметр: -v)<\\/p><p>Пример:<\\/p><p><code>curl -v https:\\/\\/example.com<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Скачивание файлов<\\/strong><\\/p><p>Самая частая задача curl — загрузка файлов.<\\/p><p>Пример:<\\/p><p><code>curl https:\\/\\/example.com\\/file.zip<\\/code><\\/p><p>Файл будет выведен в терминал.<\\/p><p>&nbsp;<\\/p><p><strong>Сохранение файла под указанным именем <\\/strong>(параметр: -o)<\\/p><p>Например:<\\/p><p><code>curl -o archive.zip https:\\/\\/example.com\\/file.zip<\\/code><\\/p><p>После выполнения, в текущем каталоге, появится файл: archive.zip<\\/p><p>Проверка:<\\/p><p><code>ls<\\/code><\\/p><p>Результат:<\\/p><p><code>archive.zip<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Сохранение с оригинальным именем <\\/strong>(параметр: -O)<\\/p><p>Пример:<\\/p><p><code>curl -O https:\\/\\/example.com\\/file.zip<\\/code><\\/p><p>Если сервер отдаёт файл:<\\/p><p><code>file.zip<\\/code><\\/p><p>то он будет сохранён под этим именем.<\\/p><p>&nbsp;<\\/p><p><strong>Сохранение ответа в файл<\\/strong><\\/p><p>Иногда нужно сохранить ответ сервера.<\\/p><p>Пример:<\\/p><p><code>curl https:\\/\\/example.com -o page.html<\\/code><\\/p><p>Теперь HTML сохранён. Можно открыть:<\\/p><p><code>cat page.html<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Передача данных POST (параметр: -d)<\\/strong><\\/p><p>Команда curl позволяет не только получать данные (HTTP-метод GET), но и отправлять данные на сервер (HTTP-метод POST). Это нужно, например, при получении данных от пользователя с помощью HTML-форм и отправки их на сервер с последующим сохранением.<\\/p><p>Разница между HTTP-методами GET и POST, а также информация о других HTTP-методах, а также о протоколе HTTP - выходит за рамки данного курса.<\\/p><p>&nbsp;<\\/p><p>Пример:<\\/p><p><code>curl -d \\\"name=Alex&amp;age=20\\\" https:\\/\\/example.com\\/form<\\/code><\\/p><p>Отправляется:<\\/p><p><code>name=Alex<\\/code><\\/p><p><code>age=20<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>Не проверять URL перед загрузкой.<\\/p><p>Игнорировать HTTP-заголовки при поиске ошибок.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>Перед загрузкой крупных файлов проверяйте заголовки командой curl -I.<\\/p>\",\"tests\":[{\"question\":\"Какой параметр показывает только HTTP-заголовки?\",\"answers\":[\"-o\",\"-h\",\"-I\",\"-v\"],\"correct\":2},{\"question\":\"Какой параметр сохраняет файл под указанным именем?\",\"answers\":[\"-o\",\"-O\",\"-I\",\"-v\"],\"correct\":0},{\"question\":\"Что показывает заголовок Content-Type?\",\"answers\":[\"Тип HTTP-запроса\",\"Тип содержимого\",\"Имя пользователя\",\"IP-адрес клиента\"],\"correct\":1},{\"question\":\"Что обычно содержит заголовок Content-Length?\",\"answers\":[\"Количество запросов\",\"Размер передаваемых данных\",\"Имя сервера\",\"Версию браузера\"],\"correct\":1},{\"question\":\"Куда curl выводит ответ без параметров сохранения?\",\"answers\":[\"В архив\",\"В терминал\",\"В отдельный журнал\",\"В домашний каталог\"],\"correct\":1},{\"question\":\"Какой командой можно просмотреть сохранённый текстовый файл?\",\"answers\":[\"cat\",\"read\",\"history\",\"man\"],\"correct\":0},{\"question\":\"Какая команда сохранит страницу в файл page.html?\",\"answers\":[\"curl -I page.html\",\"curl -o page.html https:\\/\\/example.com\",\"curl -O page.html\",\"curl -v page.html https:\\/\\/example.com\"],\"correct\":1}],\"tasks\":[{\"task\":\"Проверьте установку curl.\\r\\n(Команда: curl --version)\\r\\nОпределите:\\r\\nверсию программы; \\r\\nподдерживаемые протоколы. \"}]}', 1),
(13, 'Работа с API при помощи curl', 'work-with-api-by-curl', 9, '{\"theory\":\"<p>Подготовьте рабочую среду GitHub Codespaces.<\\/p><p>Скопируйте и выполните команды:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p ~\\/api-lesson\\r\\ncd ~\\/api-lesson<\\/code><\\/pre><p>&nbsp;<\\/p><p><strong>Программа jq<\\/strong><\\/p><p>В этом уроке мы будем получать с сервера данные в формате JSON.<\\/p><p>Для красивого отображения JSON нужно установить программу jq.<\\/p><p>Программы в среде Linux в дистрибутиве Ubuntu осуществляется с помощью команд sudo apt.<br>(изучим эти команды позже в этом курсе, пока просто выполните их).<\\/p><pre><code class=\\\"language-plaintext\\\">sudo apt update<\\/code><\\/pre><pre><code class=\\\"language-plaintext\\\">sudo apt install jq -y<\\/code><\\/pre><p>Проверить установку:<\\/p><p><code>jq --version<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>jq-1.7<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Что такое REST API<\\/strong><\\/p><p>API (Application Programming Interface) — это интерфейс, через который одна программа получает данные от другой.<\\/p><p>REST API — наиболее распространённый способ обмена данными через HTTP.<\\/p><p>Чаще всего сервер возвращает данные в формате JSON.<\\/p><p>В этой лекции будем использовать бесплатный учебный сервис:<\\/p><p><code>https:\\/\\/jsonplaceholder.typicode.com<\\/code><\\/p><p>Он позволяет безопасно выполнять GET- и POST-запросы без регистрации.<\\/p><p>&nbsp;<\\/p><p>Подробный разбор что такое REST API выходит за рамки данного курса.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое JSON<\\/strong><\\/p><p>JSON (JavaScript Object Notation) — текстовый формат хранения данных.<\\/p><p>Пример:<\\/p><pre><code class=\\\"language-plaintext\\\">{\\r\\n  \\\"id\\\": 1,\\r\\n  \\\"name\\\": \\\"Ruslan\\\",\\r\\n  \\\"city\\\": \\\"Almaty\\\"\\r\\n}<\\/code><\\/pre><p>JSON состоит из пар:<\\/p><p>\\\"ключ\\\": значение<\\/p><p>&nbsp;<\\/p><p>Подробный разбор что такое JSON выходит за рамки данного курса.<\\/p><p>&nbsp;<\\/p><p><strong>GET-запросы<\\/strong><\\/p><p>GET используется для получения данных.<\\/p><p>Получим список постов (имитируется социальная сеть или блог):<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/posts<\\/code><\\/p><p>Будет выведен большой JSON-массив.<\\/p><p>&nbsp;<\\/p><p>Получить одну запись:<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/posts\\/1<\\/code><\\/p><p>Пример результата:<\\/p><pre><code class=\\\"language-plaintext\\\">{\\r\\n  \\\"userId\\\": 1,\\r\\n  \\\"id\\\": 1,\\r\\n  \\\"title\\\": \\\"sunt aut facere repellat provident occaecati excepturi optio reprehenderit\\\",\\r\\n  \\\"body\\\": \\\"quia et suscipit\\\\nsuscipit recusandae consequuntur expedita et cum\\\\nreprehenderit molestiae ut ut quas totam\\\\nnostrum rerum est autem sunt rem eveniet architecto\\\"\\r\\n}<\\/code><\\/pre><p>Получить список пользователей:<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/users<\\/code><\\/p><p>&nbsp;<\\/p><p>Получить первого пользователя (с ID = 1):<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/users\\/1<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Форматирование JSON при помощи jq<\\/strong><\\/p><p>Без jq JSON выводится одной длинной строкой без форматирования.<\\/p><p>iq позволяет делать вывод форматированным, более красивым и читаемым.<\\/p><p>&nbsp;<\\/p><p>Использование:<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/posts\\/1 | jq<\\/code><\\/p><p>Результат станет более читаемым.<\\/p><p>(Конструкция | (вертикальная черта) позволяет в одной строке записать несколько последовательных команд.<br>(изучим её позже)).<\\/p><p>&nbsp;<\\/p><p>Вывести только поле title:<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/posts\\/1 | jq \'.title\'<\\/code><\\/p><p>Пример:<\\/p><p><code>\\\"sunt aut facere...<\\/code><\\/p><p>&nbsp;<\\/p><p>Вывести имя первого пользователя:<\\/p><p><code>curl https:\\/\\/jsonplaceholder.typicode.com\\/users | jq \'.[0].name\'<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>POST-запросы<\\/strong><\\/p><p>POST используется для отправки данных на сервер.<\\/p><p>Пример:<\\/p><pre><code class=\\\"language-plaintext\\\">curl -X POST https:\\/\\/jsonplaceholder.typicode.com\\/posts \\\\\\r\\n-H \\\"Content-Type: application\\/json\\\" \\\\\\r\\n-d \'{\\\"title\\\":\\\"Линукс\\\",\\\"body\\\":\\\"урок по curl\\\",\\\"userId\\\":1}\'<\\/code><\\/pre><p>Пример ответа:<\\/p><pre><code class=\\\"language-plaintext\\\">{\\r\\n  \\\"title\\\":\\\"Линукс\\\",\\r\\n  \\\"body\\\":\\\"урок по curl\\\",\\r\\n  \\\"userId\\\":1,\\r\\n  \\\"id\\\":101\\r\\n}<\\/code><\\/pre><p>Сервис JSONPlaceholder не сохраняет запись навсегда. Он лишь показывает, как выглядит успешный ответ сервера.<\\/p><p>&nbsp;<\\/p><p><strong>Когда используется на практике ?<\\/strong><\\/p><p>REST API используется практически во всех современных приложениях.<\\/p><p>- Получение информации о погоде со специализированных сервисов.<\\/p><p>- получение информации с сервисов ЖД и авиа расписаний, продажи и ареды недвижимости, сервисов трудоустройства, и т.п.<\\/p><p>- Работа с GitHub API.<\\/p><p>- Получение данных интернет-магазинов.<\\/p><p>- Автоматизация работы веб-сервисов.<\\/p><p>- Интеграция различных программ.<\\/p><p>- И многое другое<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Отправлять POST-запросы на неизвестные серверы без понимания их назначения.<\\/p><p>- Использовать API без чтения документации.<\\/p><p>- Хранить секретные ключи API в открытых файлах.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Использовать jq для просмотра JSON.<\\/p><p>- Изучать документацию API перед использованием.<\\/p><p>- Использовать учебные сервисы для экспериментов.<\\/p>\",\"tests\":[{\"question\":\"Что такое REST API?\",\"answers\":[\"API для ресторанов\",\"Текстовый редактор в Linux Ubuntu\",\"Команда Linux\",\"Интерфейс обмена данными между программами\"],\"correct\":3},{\"question\":\"Какой формат данных чаще всего используется REST API?\",\"answers\":[\"XML\",\"CSV\",\"JSON\",\"TXT\"],\"correct\":2},{\"question\":\"Какая команда выполняет GET-запрос?\",\"answers\":[\"curl URL\",\"GET URL\",\"query GET\",\"curl GET\"],\"correct\":0},{\"question\":\"Для чего используется POST?\",\"answers\":[\"Для получения данных от сервера\",\"Для отправки данных на сервер\",\"Для просмотра каталогов на сервере\",\"Для поиска файлов на сервере\"],\"correct\":1},{\"question\":\"Какая программа красиво форматирует JSON?\",\"answers\":[\"grep\",\"jq\",\"format-JSON\",\"json -format\"],\"correct\":1},{\"question\":\"Как проверить установлен ли jq?\",\"answers\":[\"jq --version\",\"jq --help\",\"jq\",\"version jq\"],\"correct\":0},{\"question\":\"Что делает параметр -X POST?\",\"answers\":[\"Удаляет файл\",\"Задаёт HTTP-метод POST\",\"Создаёт каталог\",\"Форматирует JSON\"],\"correct\":1}],\"tasks\":[{\"task\":\"По URL \\r\\nhttps:\\/\\/jsonplaceholder.typicode.com\\/comments\\r\\nПолучите список комментариев.\"},{\"task\":\"Получите третий комментарий.\"},{\"task\":\"Отправьте POST-запрос с собственными значениями title, body и userId.\"},{\"task\":\"Получите несколько различных объектов JSONPlaceholder и извлеките из каждого только одно нужное поле при помощи jq.\"}]}', 1),
(14, 'Сетевые команды Linux', 'net-commands-linux', 10, '{\"theory\":\"<p>Все команды этой лекции будут работать без создания дополнительных файлов и каталогов.<\\/p><p>&nbsp;<\\/p><p><strong>Команда hostname<\\/strong><\\/p><p>Команда hostname показывает имя текущего компьютера (хоста). В Linux каждое устройство в сети имеет своё имя.<\\/p><p>Выполните:<\\/p><p><code>hostname<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>codespaces-479e89<\\/code><\\/p><p>В GitHub Codespaces имя обычно создаётся автоматически.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>- Просмотр имени сервера.<\\/p><p>- Проверка, к какому компьютеру выполнено подключение.<\\/p><p>- Диагностика сетевых проблем.<\\/p><p>&nbsp;<\\/p><p><strong>Команда ip<\\/strong><\\/p><p>Команда ip — основная современная команда для просмотра и настройки сетевых интерфейсов Linux.<\\/p><p>В данной лекции будем использовать только просмотр информации.<\\/p><p>Выполните:<\\/p><p><code>ip a<\\/code><\\/p><p>Фрагмент вывода:<\\/p><p><code>1: lo: ...<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; inet 127.0.0.1\\/8<\\/code><\\/p><p><code>2: eth0: ...<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; inet 10.0.0.15\\/24<\\/code><\\/p><p>Здесь:<\\/p><p><code>lo<\\/code> — локальный интерфейс (localhost).<\\/p><p><code>eth0<\\/code> — сетевой интерфейс.<\\/p><p><code>inet<\\/code> — IPv4-адрес.<\\/p><p>Локальный адрес 127.0.0.1 существует на каждом компьютере и используется самим компьютером для обращения к себе.<\\/p><p>&nbsp;<\\/p><p><code>ip a<\\/code> - это наиболее важная команда.<\\/p><p>Она показывает:<\\/p><p>- сетевые интерфейсы<\\/p><p>- IP-адреса<\\/p><p>- состояние интерфейсов<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>- Просмотр IP-адреса компьютера.<\\/p><p>- Проверка работы сетевого интерфейса.<\\/p><p>- Диагностика сети.<\\/p><p>&nbsp;<\\/p><p><strong>Команда ping<\\/strong><\\/p><p>Команда ping проверяет, доступен ли другой компьютер в сети.<\\/p><p>Она отправляет небольшие сетевые пакеты и ожидает ответ.<\\/p><p>&nbsp;<\\/p><p>Проверьте, установлена ли команда ping в вашем Github Codespaces:<\\/p><p><code>ping --version<\\/code><\\/p><p>Если вывод будет подобен:<\\/p><p><code>bash: ping: command not found<\\/code><\\/p><p>-программа ping в вашем окружении не установлена.<\\/p><p>Установите программу ping:<\\/p><p><code>sudo apt update<\\/code><\\/p><p><code>sudo apt install iputils-ping<\\/code><\\/p><p>Проверьте установку:<\\/p><p><code>ping --version<\\/code><\\/p><p>Если отобразится список опций команды ping - установка прошла успешно.<\\/p><p>&nbsp;<\\/p><p>Синтаксис:<\\/p><p><code>ping адрес<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример проверки локального компьютера:<\\/p><p><code>ping 127.0.0.1<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>PING 127.0.0.1 ...<\\/code><\\/p><p><code>64 bytes from 127.0.0.1 ...<\\/code><\\/p><p><code>64 bytes from 127.0.0.1 ...<\\/code><\\/p><p>Остановить выполнение можно сочетанием клавиш:<\\/p><p><code>Ctrl+C<\\/code><\\/p><p>&nbsp;<\\/p><p>Если узел недоступен, можно увидеть сообщения:<\\/p><p><code>Request timeout<\\/code> &nbsp; (запрос превысил время)&nbsp;<\\/p><p>или<\\/p><p><code>Destination Host Unreachable<\\/code> &nbsp; (назначения хост не достижим)<\\/p><p>&nbsp;<\\/p><p>Командой ping можно проверять также доступность сайтов во внешнем интернете по доменному имени или ip-адресу, но в Github Codespaces проверить это мы не сможем.<\\/p><p>Команда ping используется для проверки доступности узлов по протоколу ICMP. В некоторых облачных средах, включая GitHub Codespaces, ICMP заблокирован. В этом случае ping покажет 100% потерь пакетов даже при исправном подключении к Интернету.<\\/p><p>Однако на обычном компьютере с Linux, или на реальном удалённом сервере - ping всегда работает.<\\/p><p>&nbsp;<\\/p><p>Если, всё-таки, нужно проверить доступность реального сервера в интернет (или ip-адреса) из под Github Codespaces используйте обычный curl:<\\/p><p><code>curl -I https:\\/\\/example.com<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда команда ping используется на практике ?<\\/p><p>- Проверка подключения к сети.<\\/p><p>- Проверка доступности сервера.<\\/p><p>- Поиск неисправностей сети.<\\/p><p>&nbsp;<\\/p><p>Краткое сравнение команд<\\/p><p>hostname — показывает имя компьютера.<\\/p><p>ip a — показывает сетевые интерфейсы и IP-адреса.<\\/p><p>ping — проверяет доступность другого узла.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>Путать имя компьютера и IP-адрес — это разные вещи.<\\/p><p>Делать вывод о неисправности сети только по одному неудачному ping.<\\/p><p>Путать адрес 127.0.0.1 с адресом другого компьютера.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>Перед диагностикой сначала узнать имя компьютера командой hostname.<\\/p><p>При проверке сети сначала посмотреть IP-адрес командой ip a.<\\/p><p>Использовать ping как первый инструмент проверки соединения.<\\/p><p>Запоминать, что 127.0.0.1 всегда указывает на текущий компьютер.<\\/p>\",\"tests\":[{\"question\":\"Какая команда показывает имя компьютера?\",\"answers\":[\"ping\",\"hostname\",\"name\",\"whoami\"],\"correct\":1},{\"question\":\"Какая команда показывает IP-адрес компьютера?\",\"answers\":[\"ip-adress\",\"hostname\",\"ip\",\"ip-host\"],\"correct\":2},{\"question\":\"Что такое IP-адрес?\",\"answers\":[\"Адрес пользователя IP\",\"Адрес компьютера в сети\",\"Адрес каталога в интернете\",\"Адрес процесса Linux\"],\"correct\":1},{\"question\":\"Какая команда проверяет доступность узла?\",\"answers\":[\"curl\",\"ping\",\"hostname\",\"history\"],\"correct\":1},{\"question\":\"Какой адрес соответствует локальному компьютеру?\",\"answers\":[\"0.0.0.0\",\"255.255.255.255\",\"127.0.0.1\",\"8.8.8.8\"],\"correct\":2},{\"question\":\"Как остановить выполнение команды ping?\",\"answers\":[\"Ctrl+Q\",\"Ctrl+R\",\"Ctrl+C\",\"Esc\"],\"correct\":2},{\"question\":\"Что показывает команда ip a?\",\"answers\":[\"Сетевые интерфейсы и IP-адреса\",\"Все IP-адреса начинающиеся на a\",\"Размер памяти для команды IP\",\"Список процессов использующих IP\"],\"correct\":0},{\"question\":\"Какая команда чаще всего используется первой при проверке доступности сервера?\",\"answers\":[\"hostname\",\"pwd\",\"check\",\"ping\"],\"correct\":3}],\"tasks\":[{\"task\":\"Определите имя текущего компьютера.\\r\\nПросмотрите все сетевые интерфейсы и найдите IP-адрес.\"},{\"task\":\"Определите, какой сетевой интерфейс используется для подключения к сети, просмотрев вывод команды ip a.\"},{\"task\":\"Используя только команды hostname, ip и ping, выполните базовую диагностику сети и определите: имя компьютера, его IP-адрес и доступность локального адреса 127.0.0.1.\"}]}', 1),
(15, 'Диагностика сети', 'net-diagnostic', 11, '{\"theory\":\"<p>Для примеров этой лекции дополнительная подготовка GitHub Codespaces не требуется.<\\/p><p>&nbsp;<\\/p><p><strong>Команда ss<\\/strong><\\/p><p>Команда ss (Socket Statistics) предназначена для просмотра сетевых соединений Linux.<\\/p><p>С её помощью можно узнать:<\\/p><p>TCP-соединения.<\\/p><p>UDP-соединения.<\\/p><p>В современных версиях Linux команда ss практически полностью заменила устаревшую команду netstat.<\\/p><p>&nbsp;<\\/p><p>Синтаксис<\\/p><p><code>ss [параметры]<\\/code><\\/p><p>Наиболее полезные параметры<\\/p><p><code>-t<\\/code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; показать TCP-соединения<\\/p><p><code>-u<\\/code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; показать UDP-соединения<\\/p><p><code>-l<\\/code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; показать только прослушиваемые порты<\\/p><p><code>-a<\\/code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; показать все соединения<\\/p><p><code>-n<\\/code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; не преобразовывать номера портов в имена<\\/p><p>На практике чаще всего используются комбинации параметров.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр TCP-соединений<\\/strong><\\/p><p><code>ss -t<\\/code><\\/p><p>Пример вывода:<\\/p><pre><code class=\\\"language-plaintext code-block-tiny\\\" style=\\\"font-size:50%;\\\">State&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Recv-Q&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Send-Q&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Local Address:Port&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Peer Address:Port&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Process&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nESTAB&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 10.0.1.148:38726&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 52.239.135.100:https&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nESTAB&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 10.0.1.148:38716&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 52.239.135.100:https&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nESTAB&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 10.0.1.148:54982&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 52.239.202.36:https&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <\\/code><\\/pre><p>Здесь видно:<\\/p><p>TCP-соединение установлено.<\\/p><p>Используется для проверки активных TCP-подключений.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр UDP-соединений<\\/strong><\\/p><p><code>ss -u<\\/code><\\/p><p>UDP не устанавливает соединение перед передачей данных, поэтому вывод отличается от TCP.<\\/p><p>Используется для просмотра программ, работающих через UDP.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр прослушиваемых портов<\\/strong><\\/p><p><code>ss -l<\\/code><\\/p><p>LISTEN означает, что программа ожидает входящих подключений.<\\/p><p>Так можно проверить, какие сетевые службы работают на компьютере.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр всех TCP-портов в режиме прослушивания<\\/strong><\\/p><p><code>ss -tl<\\/code><\\/p><p>Пример вывода:<\\/p><pre><code class=\\\"language-plaintext code-block-tiny\\\" style=\\\"font-size:50%;\\\">State&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Recv-Q&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Send-Q&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Local Address:Port&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Peer Address:Port&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Process&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nLISTEN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 128&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0.0.0.0:2222&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0.0.0.0:*&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nLISTEN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 127.0.0.1:40083&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0.0.0.0:*&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \\r\\nLISTEN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 4096&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 127.0.0.53%lo:domain&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0.0.0.0:*&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <\\/code><\\/pre><p>&nbsp;<\\/p><p>Параметры можно объединять.<\\/p><p>Просмотр всех UDP-портов<\\/p><p><code>ss -ul<\\/code><\\/p><p>Используется аналогично предыдущей команде, но только для UDP.<\\/p><p>&nbsp;<\\/p><p><strong>Просмотр всех соединений<\\/strong><\\/p><p><code>ss -a<\\/code><\\/p><p>Показываются:<\\/p><p>активные соединения;<\\/p><p>прослушиваемые порты;<\\/p><p>некоторые внутренние сокеты Linux.<\\/p><p>&nbsp;<\\/p><p><strong>Отключение преобразования имён<\\/strong><\\/p><p><code>ss -tn<\\/code><\\/p><p>Параметр -n оставляет только числовые номера портов и IP-адреса.<\\/p><p>Так вывод получается короче и создаётся быстрее.<\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>- Проверка работы сетевых сервисов.<\\/p><p>- Поиск открытых портов.<\\/p><p>- Проверка установленных соединений.<\\/p><p>- Диагностика проблем с подключением.<\\/p><p>- Проверка, запущен ли нужный сервер.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Использовать ss без понимания разницы между TCP и UDP.<\\/p><p>- Путать прослушиваемые порты с активными соединениями.<\\/p><p>- Игнорировать параметр -n, когда нужен компактный вывод.<\\/p><p>- Делать вывод о работе сервиса только по одному соединению.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Начинать диагностику с ss -tl.<\\/p><p>- Использовать ss -tn для быстрого просмотра соединений.<\\/p><p>- Различать состояния LISTEN и ESTAB.<\\/p><p>- Проверять TCP и UDP отдельно.<\\/p><p>- Использовать ss вместо устаревшей команды netstat.<\\/p>\",\"tests\":[{\"question\":\"Что показывает команда ss?\",\"answers\":[\"Память компьютера\",\"Сетевые соединения\",\"Процессы\",\"Файловую систему\"],\"correct\":1},{\"question\":\"Какая команда показывает TCP-соединения?\",\"answers\":[\"ss -u\",\"ss -t\",\"ss -tcp\",\"ss -a\"],\"correct\":1},{\"question\":\"Какая команда показывает UDP-соединения?\",\"answers\":[\"ss -u\",\"ss -t\",\"ss -n\",\"ss -udp\"],\"correct\":0},{\"question\":\"Что означает состояние LISTEN?\",\"answers\":[\"Соединение разорвано\",\"Программа ожидает входящих подключений\",\"Передача данных завершена\",\"Ошибка сети\"],\"correct\":1},{\"question\":\"Какая команда показывает прослушиваемые TCP-порты?\",\"answers\":[\"ss -tl\",\"ss -tcp\",\"ss -listen\",\"ss -tu\"],\"correct\":0},{\"question\":\"Что делает параметр -n?\",\"answers\":[\"Закрывает соединения\",\"Показывает только новые соединения\",\"Отключает преобразование имён\",\"Выводит номера процессов\"],\"correct\":2},{\"question\":\"Какая команда показывает все соединения?\",\"answers\":[\"ss -a\",\"ss -t\",\"ss -l\",\"ss -all\"],\"correct\":0},{\"question\":\"Какой протокол устанавливает соединение перед передачей данных?\",\"answers\":[\"UDP\",\"TCP\",\"DNS\",\"HTTP\"],\"correct\":1},{\"question\":\"Для чего чаще всего используют команду ss?\",\"answers\":[\"Создания пользователей в ОС Linux\",\"Просмотра сетевых соединений и открытых портов\",\"Редактирования файлов\",\"Архивирования данных алгоритмом ss\"],\"correct\":1}],\"tasks\":[{\"task\":\"Просмотрите все TCP-соединения вашего пространства codespace с и без преобразования имён. Проанализируйте вывод, на уровне ваших текущих знаний, что означает вся эта информация.\"},{\"task\":\"Определите, есть ли на компьютере соединения в состоянии ESTAB.\"},{\"task\":\"Определите, какие TCP-порты находятся в состоянии LISTEN\"}]}', 1),
(16, 'Управление пакетами Ubuntu', 'apt-get', 12, '{\"theory\":\"<p><strong>Подготовка среды GitHub Codespaces<\\/strong><\\/p><p>GitHub Codespaces уже содержит Ubuntu и менеджер пакетов apt. Для выполнения примеров достаточно проверить, что необходимые команды доступны.<\\/p><p><code>apt --version<\\/code><\\/p><p><code>apt-cache --version<\\/code><\\/p><p><code>dpkg --version<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>apt 2.8.3 (amd64)<\\/code><\\/p><p><code>apt 2.8.3 (amd64)<\\/code><\\/p><p><code>Debian \'dpkg\' package management program version 1.22.6 (amd64).<\\/code><\\/p><p><code>This is free software; see the GNU General Public License version 2 or<\\/code><\\/p><p><code>later for copying conditions. There is NO warranty.<\\/code><\\/p><p>&nbsp;<\\/p><p>Большинство команд этой лекции, изменяющих систему (установка и удаление программ), требуют прав администратора (super user), которые включаются командой sudo, которая пишется перед необходимой командой.<\\/p><p>В GitHub Codespaces такие команды доступны.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Что такое пакет<\\/strong><\\/p><p>В Ubuntu программы распространяются в виде пакетов.<\\/p><p>Пакет содержит:<\\/p><p>- исполняемые файлы программы<\\/p><p>- библиотеки<\\/p><p>- файлы настройки<\\/p><p>- служебную информацию<\\/p><p>При установке пакета все необходимые файлы автоматически помещаются в нужные каталоги.<\\/p><p>Например, браузер, текстовый редактор или архиватор устанавливаются именно как пакеты.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое репозиторий<\\/strong><\\/p><p>Репозиторий — это сервер, на котором хранятся тысячи готовых пакетов Ubuntu.<\\/p><p>Когда выполняется установка программы, apt:<\\/p><p>- подключается к репозиторию<\\/p><p>- находит нужный пакет<\\/p><p>- скачивает его<\\/p><p>- устанавливает<\\/p><p>При необходимости автоматически устанавливаются зависимости — дополнительные пакеты, без которых программа работать не сможет.<\\/p><p>&nbsp;<\\/p><p><strong>Команда apt<\\/strong><\\/p><p>apt — основной инструмент установки, обновления и удаления программ.<\\/p><p>Синтаксис:<\\/p><p><code>apt &lt;команда&gt; [пакет]<\\/code><\\/p><p>Наиболее важные команды<\\/p><p><code>update<\\/code> — обновляет список пакетов<\\/p><p><code>search<\\/code> — ищет пакеты в репозиториях по имени или части имени<\\/p><p><code>show<\\/code> — показывает подробную информацию о пакете.<\\/p><p><code>install<\\/code> — устанавливает пакет<\\/p><p><code>remove<\\/code> — удаляет пакет<\\/p><p><code>upgrade<\\/code> — обновляет установленные пакеты<\\/p><p><code>apt list --installed<\\/code> — показывает список всех установленных пакетов.<\\/p><p>&nbsp;<\\/p><p>Поскольку установка и удаление пакетов требует права главного администратора (в терминологии Linux - Super User - Суперпользователь), перед командой apt всегда добавляется команда sudo, включающая режим суперпользователя.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p>Обновим список пакетов:<\\/p><p><code>sudo apt update<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>. . .<\\/code><\\/p><p><code>Reading package lists... Done<\\/code><\\/p><p><code>Building dependency tree... Done<\\/code><\\/p><p><code>Reading state information... Done<\\/code><\\/p><p><code>1 package can be upgraded. Run \'apt list --upgradable\' to see it.<\\/code><\\/p><p>&nbsp;<\\/p><p>Найдём пакет в репозиториях. Для примера пакет htop.<\\/p><p><code>sudo apt search htop<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Sorting... Done<\\/code><\\/p><p><code>Full Text Search... Done<\\/code><\\/p><p><code>bashtop\\/noble 0.9.25-1 all<\\/code><\\/p><p><code>&nbsp; Resource monitor that shows usage and stats<\\/code><\\/p><p><code>htop\\/noble,now 3.3.0-4build1 amd64 [installed]<\\/code><\\/p><p><code>&nbsp; interactive processes viewer<\\/code><\\/p><p>&nbsp;<\\/p><p>Прочитаем информацию о пакете. Например: пакет tree<\\/p><p><code>sudo apt show tree<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Package: tree<\\/code><\\/p><p><code>Version: 2.1.1-2ubuntu3.24.04.2<\\/code><\\/p><p><code>Priority: optional<\\/code><\\/p><p><code>Section: universe\\/utils<\\/code><\\/p><p><code>. . .<\\/code><\\/p><p>&nbsp;<\\/p><p>Установим пакет (программу, приложение, утилиту). Для примера tree:<\\/p><p><code>sudo apt install tree<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример вывода:<\\/p><p><code>The following NEW packages will be installed:<\\/code><\\/p><p><code>tree<\\/code><\\/p><p>&nbsp;<\\/p><p>Запустите программу:<\\/p><p><code>tree<\\/code><\\/p><p>Самостоятельно сделайте вывод - что делает программа<\\/p><p>&nbsp;<\\/p><p>Посмотри список всех установленных пакетов.<\\/p><p><code>apt list --installed<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Listing... Done<\\/code><\\/p><p><code>adduser\\/noble,now 3.137ubuntu1 all [installed,automatic]<\\/code><\\/p><p><code>apt-transport-https\\/noble-updates,now 2.8.3 all [installed]<\\/code><\\/p><p><code>apt-utils\\/noble-updates,now 2.8.3 amd64 [installed]<\\/code><\\/p><p><code>. . .<\\/code><\\/p><p>Команда полезна, когда нужно проверить, установлена ли программа.<\\/p><p>&nbsp;<\\/p><p>Можно вывести только один пакет:<\\/p><p><code>apt list --installed tree<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Listing... Done<\\/code><\\/p><p><code>tree\\/noble-updates,now 2.1.1-2ubuntu3.24.04.2 amd64 [installed]<\\/code><\\/p><p>&nbsp;<\\/p><p>Если пакет не установлен, строка [installed] отсутствует.<\\/p><p>&nbsp;<\\/p><p>Удалить программу:<\\/p><p><code>sudo apt remove tree<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Reading package lists... Done<\\/code><\\/p><p><code>Building dependency tree... Done<\\/code><\\/p><p><code>Reading state information... Done<\\/code><\\/p><p><code>The following packages will be REMOVED:<\\/code><\\/p><p><code>&nbsp; tree<\\/code><\\/p><p><code>0 upgraded, 0 newly installed, 1 to remove and 142 not upgraded.<\\/code><\\/p><p><code>After this operation, 111 kB disk space will be freed.<\\/code><\\/p><p>&nbsp;<\\/p><p>После удаления Bash задаёт вопрос:<\\/p><p><code>Do you want to continue? [Y\\/n]<\\/code><\\/p><p>- нужно ответить <code>Y<\\/code><\\/p><p>&nbsp;<\\/p><p>Обновить все установленные пакеты:<\\/p><p><code>sudo apt upgrade<\\/code><\\/p><p>Пример вывода:<\\/p><p><code>Reading package lists... Done<\\/code><\\/p><p><code>Calculating upgrade... Done<\\/code><\\/p><p><code>0 upgraded, 0 newly installed, 0 to remove.<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Типичный порядок работы<\\/strong><\\/p><p>Перед обновлением системы:<\\/p><p><code>sudo apt update<\\/code><\\/p><p><code>sudo apt upgrade<\\/code><\\/p><p>&nbsp;<\\/p><p>Перед установкой новой программы:<\\/p><p><code>sudo apt search Пакет<\\/code><\\/p><p><code>sudo apt show Пакет<\\/code><\\/p><p><code>sudo apt install Пакет<\\/code><\\/p><p>&nbsp;<\\/p><p>Проверка установки:<\\/p><p><code>sudo apt list --installed Пакет<\\/code><\\/p><p>&nbsp;<\\/p><p>Удаление программы:<\\/p><p><code>sudo apt remove Пакет<\\/code><\\/p><p><strong>&nbsp;<\\/strong><\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Запускать apt install без предварительного apt update<\\/p><p>- Устанавливать программы из случайных файлов .deb, не проверяя источник.<\\/p><p>- Удалять системные пакеты без понимания их назначения.<\\/p><p>- Игнорировать сообщения об ошибках во время установки.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Перед установкой обновляйте список пакетов командой apt update.<\\/p><p>- Перед установкой изучайте описание пакета через apt show.<\\/p><p>- Скачивайте .deb только с официальных сайтов или доверенных источников.<\\/p><p>- Периодически обновляйте систему командой sudo apt upgrade<\\/p>\",\"tests\":[{\"question\":\"Как называется стандартный менеджер пакетов Ubuntu?\",\"answers\":[\"npm\",\"pkg\",\"apt\",\"rpm\"],\"correct\":2},{\"question\":\"Какую команду используют для установки программы?\",\"answers\":[\"apt install\",\"npm install\",\"programm install\",\"package install\"],\"correct\":0},{\"question\":\"Что хранится в репозитории?\",\"answers\":[\"Исходный код ядра Linux\",\"Архивы пользователей\",\"Готовые пакеты программ\",\"Прикладные программы пользователя\"],\"correct\":2},{\"question\":\"Что показывает команда apt show?\",\"answers\":[\"Запущенные процессы\",\"Описание пакета\",\"Установленные пакеты\",\"Пакеты в репозитории\"],\"correct\":1},{\"question\":\"Какая команда удаляет установленную программу?\",\"answers\":[\"apt delete\",\"apt remove\",\"apt erase\",\"package delete\"],\"correct\":1},{\"question\":\"Какой формат имеют пакеты Ubuntu?\",\"answers\":[\".exe\",\".tar\",\".deb\",\".iso\"],\"correct\":2}],\"tasks\":[{\"task\":\"Найдите все пакеты, содержащие слово htop\"},{\"task\":\"Изучите информацию о пакете htop, с помощью соответствующей команды apt-… .\"},{\"task\":\"Поскольку, прочитав информацию о пакете htop на английском, вы вряд ли что то поняли - прочитайте описание этого пакета в ИИ\"},{\"task\":\"Определите, установлен ли пакет htop в системе\"},{\"task\":\"Установите пакет htop, если его ещё нет, затем убедитесь, что он появился в списке установленных пакетов\"},{\"task\":\"Запустите программу htop и проанализируйте, что делает и что показывает эта программа. Некоторое время поизучайте её вывод. Затем выйдите из этой программы\"},{\"task\":\"Удалите пакет htop и проверьте, что он больше не установлен\"}]}', 1),
(17, 'Создание файлов и каталогов', 'filees-and-direciries-creating', 13, '{\"theory\":\"<p>Перед выполнением примеров создайте учебную структуру:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p ~\\/lesson13\\r\\ncd ~\\/lesson13<\\/code><\\/pre><p>В этой лекции вы изучите три основные команды, с которых начинается создание структуры любого проекта: mkdir, touch и rmdir.<\\/p><p>&nbsp;<\\/p><p><strong>Команда mkdir<\\/strong><\\/p><p>Создаёт новый каталог.<\\/p><p>Синтаксис :<\\/p><p><code>mkdir имя_каталога<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Создать каталог docs :<\\/p><p><code>mkdir docs<\\/code><\\/p><p>Проверить результат:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример: Создать несколько каталогов:<\\/p><p><code>mkdir images backups logs<\\/code><\\/p><p>Ожидаемый вывод команды ls:<\\/p><p><code>backups&nbsp; docs&nbsp; images&nbsp; logs<\\/code><\\/p><p>&nbsp;<\\/p><p>Параметр:<\\/p><p><code>-p<\\/code><\\/p><p>позволяет создать сразу несколько вложенных каталогов.<\\/p><p>Если часть каталогов уже существует, ошибки не будет.<\\/p><p>&nbsp;<\\/p><p>Пример. Создать вложенные каталоги:<\\/p><p><code>mkdir -p project\\/src\\/tests<\\/code><\\/p><p>Проверим:<\\/p><p><code>ls project<\\/code><\\/p><p>Ожидаемый вывод :<\\/p><p><code>src<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется ?<\\/p><p>- При создании структуры проекта.<\\/p><p>- При подготовке каталогов для хранения файлов.<\\/p><p>- При организации данных.<\\/p><p>&nbsp;<\\/p><p><strong>Команда touch<\\/strong><\\/p><p>Создаёт пустой файл.<\\/p><p>Если файл уже существует, команда обновляет дату его изменения.<\\/p><p>Синтаксис<\\/p><p><code>touch имя_файла<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Создать файл:<\\/p><p><code>touch notes.txt<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>backups&nbsp; docs&nbsp; images&nbsp; logs&nbsp; notes.txt&nbsp; project<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Создать несколько файлов:<\\/p><p><code>touch app.py config.json README.md<\\/code><\\/p><p>Ожидаемый вывод команды ls:<\\/p><p><code>README.md&nbsp; app.py&nbsp; backups&nbsp; config.json&nbsp; docs&nbsp; images&nbsp; logs&nbsp; notes.txt&nbsp; project<\\/code><\\/p><p>&nbsp;<\\/p><p>Создать файлы внутри каталога:<\\/p><p><code>touch docs\\/manual.txt docs\\/index.txt<\\/code><\\/p><p>Проверим:<\\/p><p><code>ls docs<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>index.txt&nbsp; manual.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется ?<\\/p><p>- Создание новых файлов.<\\/p><p>- Подготовка структуры проекта.<\\/p><p>- Создание файлов конфигурации и журналов.<\\/p><p>&nbsp;<\\/p><p><strong>Команда rmdir<\\/strong><\\/p><p>Удаляет пустой каталог.<\\/p><p>Если внутри есть хотя бы один файл или другой каталог, команда завершится ошибкой.<\\/p><p>Синтаксис :<\\/p><p><code>rmdir имя_каталога<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Создать и удалить пустой каталог:<\\/p><p><code>mkdir temp<\\/code><\\/p><p>Проверим:<\\/p><p><code>ls<\\/code><\\/p><p>Каталог создался.<\\/p><p><code>rmdir temp<\\/code><\\/p><p>Проверим:<\\/p><p><code>ls<\\/code><\\/p><p>Каталога temp больше нет.<\\/p><p>&nbsp;<\\/p><p>Попытка удалить непустой каталог:<\\/p><p><code>mkdir test<\\/code><\\/p><p><code>touch test\\/file.txt<\\/code><\\/p><p><code>rmdir test<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>rmdir: failed to remove \'test\': Directory not empty<\\/code><\\/p><p>В этом случае сначала необходимо удалить содержимое каталога (это будет изучаться в следующих лекциях).<\\/p><p>&nbsp;<\\/p><p>Когда используется ?<\\/p><p>- Удаление ненужных пустых каталогов.<\\/p><p>- Очистка структуры проекта.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Создавать каталоги с непонятными именами вроде aaa или test1.<\\/p><p>- Использовать пробелы в именах файлов и каталогов без необходимости.<\\/p><p>- Хранить все файлы в одном каталоге.<\\/p><p>- Создавать лишние пустые каталоги.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Группируйте файлы по назначению.<\\/p><p>- Создавайте структуру проекта заранее.<\\/p><p>- Периодически удаляйте ненужные пустые каталоги.<\\/p>\",\"tests\":[{\"question\":\"Что делает команда mkdir?\",\"answers\":[\"Удаляет каталог\",\"Создаёт каталог\",\"Создаёт файл\",\"Показывает содержимое каталога\"],\"correct\":1},{\"question\":\"Как создать каталог docs?\",\"answers\":[\"touch docs\",\"mkdir docs\",\"rmdir docs\",\"cd docs\"],\"correct\":1},{\"question\":\"Какой параметр позволяет создать вложенные каталоги?\",\"answers\":[\"-r\",\"-a\",\"-p\",\"-l\"],\"correct\":2},{\"question\":\"Что создаёт команда touch?\",\"answers\":[\"Каталог\",\"Архив\",\"Пустой файл\",\"Текстовый файл\"],\"correct\":2},{\"question\":\"Какая команда удаляет пустой каталог?\",\"answers\":[\"rm\",\"delete\",\"remove\",\"rmdir\"],\"correct\":3},{\"question\":\"Почему rmdir может завершиться ошибкой?\",\"answers\":[\"Недостаточно памяти\",\"Каталог не пустой\",\"Файл открыт\",\"Команда работает только от администратора\"],\"correct\":1},{\"question\":\"Какая команда создаст каталоги project\\/src\\/tests за один раз?\",\"answers\":[\"mkdir project src tests\",\"mkdir -p project\\/src\\/tests\",\"touch project\\/src\\/tests\",\"rmdir project\\/src\\/tests\"],\"correct\":1},{\"question\":\"Какая команда создаёт несколько файлов одновременно?\",\"answers\":[\"touch a.txt b.txt c.txt\",\"mkdir a.txt b.txt c.txt\",\"files a.txt b.txt c.txt\",\"create a.txt b.txt c.txt\"],\"correct\":0}],\"tasks\":[{\"task\":\"Создайте каталог projects.\"},{\"task\":\"Создайте внутри домашнего каталога каталоги docs, images и backup одной командой.\\r\\nУбедитесь, что каталоги созданы\"},{\"task\":\"Создайте пустой файл README.md\"},{\"task\":\"Внутри каталога projects создайте структуру каталогов website\\/css и website\\/js одной командой.\\r\\nУбедитесь, что каталоги созданы\"},{\"task\":\"Создайте файлы index.html, style.css и script.js внутри соответствующих каталогов.\\r\\nУбедитесь, что файлы созданы\"},{\"task\":\"Создайте каталог reports и три пустых файла jan.txt, feb.txt и mar.txt двумя командами.\\r\\nУбедитесь, что файлы созданы\"}]}', 1);
INSERT INTO `lessons` (`id`, `title_ru`, `slug`, `lesson_order`, `content`, `is_published`) VALUES
(18, 'Копирование и перемещение', 'coping-and-moving', 14, '{\"theory\":\"<p>Перед выполнением примеров создайте в Github Codespaces учебную структуру:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p lesson14\\/docs lesson14\\/backup lesson14\\/archive\\r\\ncd lesson14\\r\\ntouch report.txt notes.txt docs\\/readme.txt<\\/code><\\/pre><p>Проверьте результат:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>archive&nbsp; backup&nbsp; docs&nbsp; notes.txt&nbsp; report.txt<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Команда cp<\\/strong><\\/p><p>Команда cp копирует файлы и каталоги.<\\/p><p>Исходный объект остаётся на месте, создаётся его копия.<\\/p><p>Синтаксис :<\\/p><p><code>cp [параметры] источник назначение<\\/code><\\/p><p>Наиболее важные параметры<\\/p><p><code>-r<\\/code> — копировать каталог вместе со всем содержимым.<\\/p><p><code>-i<\\/code> — спрашивать подтверждение перед перезаписью существующего файла.<\\/p><p>&nbsp;<\\/p><p>Пример. Копировать файл:<\\/p><p><code>cp report.txt backup\\/<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls backup<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>report.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Создать копию файла с новым именем:<\\/p><p><code>cp report.txt report-copy.txt<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>archive&nbsp; backup&nbsp; docs&nbsp; notes.txt&nbsp; report-copy.txt&nbsp; report.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Копировать каталог полностью:<\\/p><p><code>cp -r docs archive\\/<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls archive<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется ?<\\/p><p>- Создание резервных копий.<\\/p><p>- Копирование файлов между каталогами.<\\/p><p>- Копирование шаблонов проектов.<\\/p><p>&nbsp;<\\/p><p><strong>Команда mv<\\/strong><\\/p><p>Команда mv перемещает файлы и каталоги.<\\/p><p>Также она используется для переименования.<\\/p><p>Синтаксис :<\\/p><p><code>mv [параметры] источник назначение<\\/code><\\/p><p>Наиболее важные параметры:<\\/p><p><code>-i<\\/code> — спрашивать подтверждение перед перезаписью.<\\/p><p>&nbsp;<\\/p><p>Пример. Переместить файл:<\\/p><p><code>mv notes.txt backup\\/<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls backup<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>notes.txt&nbsp; report.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Переименовать файл:<\\/p><p><code>mv report-copy.txt summary.txt<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>archive&nbsp; backup&nbsp; docs&nbsp; report.txt&nbsp; summary.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример. Переместить каталог:<\\/p><p><code>mv docs archive\\/<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls archive<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется ?<\\/p><p>- Перемещение файлов.<\\/p><p>- Переименование файлов.<\\/p><p>- Организация структуры каталогов.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Перезаписывать важные файлы, не проверив назначение команды.<\\/p><p>- Использовать cp -r не убедившись, что копируется нужный каталог.<\\/p><p>- Копировать одинаковые файлы в разные места без необходимости.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Перед копированием проверяйте текущий каталог командой pwd.<\\/p><p>- После выполнения команды проверяйте результат с помощью ls.<\\/p><p>- Используйте понятные имена файлов.<\\/p><p>- Храните резервные копии в отдельном каталоге.<\\/p>\",\"tests\":[{\"question\":\"Что делает команда cp?\",\"answers\":[\"Удаляет файл или каталог\",\"Переименовывает файл или каталог\",\"Создаёт каталог\",\"Копирует файл или каталог\"],\"correct\":3},{\"question\":\"Какой параметр позволяет копировать каталог целиком?\",\"answers\":[\"-a\",\"-d\",\"-r\",\"-l\"],\"correct\":2},{\"question\":\"Какая команда переименовывает файл?\",\"answers\":[\"cp\",\"mv\",\"touch\",\"rename\"],\"correct\":1},{\"question\":\"Что происходит после выполнения команды mv file.txt backup\\/?\",\"answers\":[\"Файл перемещается в каталог backup\",\"Создаётся копия файла в каталоге backup\",\"Файл file.txt удаляется из каталога backup\",\"Создаётся архив\"],\"correct\":0},{\"question\":\"Какая команда создаёт копию файла с новым именем?\",\"answers\":[\"mv report.txt copy.txt\",\"cp report.txt copy.txt\",\"copy report.txt copy.txt\",\"new report.txt copy.txt\"],\"correct\":1},{\"question\":\"Какой параметр предлагает подтверждение перед перезаписью?\",\"answers\":[\"-v\",\"-r\",\"-n\",\"-i\"],\"correct\":3},{\"question\":\"Какая команда копирует каталог docs, со всем содержимым, в каталог backup?\",\"answers\":[\"mv docs backup\",\"cp docs backup\",\"cp -r docs backup\",\"mkdir backup\\/docs\"],\"correct\":2},{\"question\":\"Какая команда используется чаще всего для перемещения файла?\",\"answers\":[\"mv\",\"cp\",\"transfer\",\"move\"],\"correct\":0},{\"question\":\"Какая команда копирует файл report.txt в каталог archive?\",\"answers\":[\"mv report.txt archive\",\"cp report.txt archive\",\"cp archive\\/report.txt\",\"mkdir archive\\/report.txt\"],\"correct\":1}],\"tasks\":[{\"task\":\"Создайте каталог backup и скопируйте в него файл report.txt.\"},{\"task\":\"Создайте копию файла report.txt с именем report-old.txt.\"},{\"task\":\"Скопируйте файл readme.txt в текущий каталог.\"},{\"task\":\"Переместите файл notes.txt в каталог backup.\"},{\"task\":\"Переименуйте файл report.txt в report-final.txt.\"},{\"task\":\"Скопируйте каталог docs в каталог archive.\"},{\"task\":\"Переместите каталог backup внутрь каталога archive.\"},{\"task\":\"Переименуйте каталог archive в storage, сохранив всё его содержимое.\"}]}', 1),
(19, 'Удаление файлов', 'files-deleting', 15, '{\"theory\":\"<p>Команда rm используется для удаления файлов и каталогов. В отличие от перемещения или копирования, удаление — потенциально опасная операция: после выполнения rm файл обычно нельзя восстановить обычными средствами Linux.<\\/p><p>&nbsp;<\\/p><p>Подготовка среды GitHub Codespaces. Создайте учебную структуру:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p lesson15\\/docs lesson15\\/archive\\r\\ntouch lesson15\\/file1.txt lesson15\\/file2.txt\\r\\ntouch lesson15\\/docs\\/report.txt lesson15\\/docs\\/notes.txt\\r\\ntouch lesson15\\/archive\\/old.txt<\\/code><\\/pre><p>&nbsp;<\\/p><p>Перейдите в каталог:<\\/p><p><code>cd lesson15<\\/code><\\/p><p>Проверьте структуру:<\\/p><p><code>ls -la<\\/code><\\/p><p>Ожидаемый примерный вывод:<\\/p><p><code>total ...<\\/code><\\/p><p><code>drwxr-xr-x ... archive<\\/code><\\/p><p><code>drwxr-xr-x ... docs<\\/code><\\/p><p><code>-rw-r--r-- ... file1.txt<\\/code><\\/p><p><code>-rw-r--r-- ... file2.txt<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Команда rm<\\/strong><\\/p><p>rm удаляет файлы.<\\/p><p>Синтаксис:<\\/p><p><code>rm имя_файла<\\/code><\\/p><p>Например:<\\/p><p><code>rm file1.txt<\\/code><\\/p><p>После выполнения file1.txt больше не будет находиться в текущем каталоге.<\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>archive&nbsp; docs&nbsp; file2.txt<\\/code><\\/p><p>&nbsp;<\\/p><p>Удаление нескольких файлов<\\/p><p>Можно указать несколько файлов одной командой:<\\/p><p><code>rm file2.txt docs\\/report.txt<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>archive&nbsp; docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Безопасное удаление<\\/p><p>Перед удалением важного файла полезно сначала убедиться, что указано именно то имя, которое требуется удалить.<\\/p><p>Например:<\\/p><p><code>ls docs<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>notes.txt<\\/code><\\/p><p>После проверки можно удалить файл:<\\/p><p><code>rm docs\\/notes.txt<\\/code><\\/p><p>Проверка:<\\/p><p><code>ls docs<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><i>(ничего)<\\/i><\\/p><p>&nbsp;<\\/p><p>Если имя файла содержит пробелы, его заключают в кавычки:<\\/p><p><code>rm \\\"my report.txt\\\"<\\/code><\\/p><p>&nbsp;<\\/p><p>В учебной и рабочей практике особенно важно внимательно проверять путь: команда rm не спрашивает подтверждение при обычном удалении.<\\/p><p>&nbsp;<\\/p><p><strong>Рекурсивное удаление каталогов<\\/strong><\\/p><p>Обычная команда rm удаляет файлы, но не удаляет каталог вместе с его содержимым.<\\/p><p>Например:<\\/p><p><code>rm archive<\\/code><\\/p><p>Ожидаемый результат:<\\/p><p><code>rm: cannot remove \'archive\': Is a directory<\\/code><\\/p><p>&nbsp;<\\/p><p>Для удаления каталога вместе со всем его содержимым используется параметр -r:<\\/p><p><code>rm -r archive<\\/code><\\/p><p>Теперь каталог archive и файл archive\\/old.txt удалены.<\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>docs<\\/code><\\/p><p>&nbsp;<\\/p><p>Параметр -r означает рекурсивное удаление: команда проходит по каталогу и удаляет его содержимое, включая вложенные каталоги.<\\/p><p>Например, чтобы удалить каталог docs вместе с находящимися внутри файлами:<\\/p><p><code>rm -r docs<\\/code><\\/p><p>Проверить:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><i>(ничего)<\\/i><\\/p><p>&nbsp;<\\/p><p>После этого каталог lesson15 также можно удалить, вернувшись на уровень выше:<\\/p><p><code>cd ..<\\/code><\\/p><p><code>rm -r lesson15<\\/code><\\/p><p>&nbsp;<\\/p><p>Параметр -f позволяет принудительно удалять файлы без запроса подтверждения и подавляет некоторые сообщения об ошибках.<\\/p><p>Для начинающих пользователей его следует применять особенно осторожно.<\\/p><p>Комбинация <code>rm -rf<\\/code> может удалить большое дерево каталогов без подтверждения.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Удалять файлы, не проверив имя и путь.<\\/p><p>- Использовать rm -rf, не понимая, какой каталог будет удалён.<\\/p><p>- Привыкать использовать rm -f для всех операций.<\\/p><p>- Удалять каталог рекурсивно, не проверив его содержимое.<\\/p><p>- Использовать команды удаления в незнакомом каталоге без предварительного pwd и ls.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Перед опасным удалением проверить текущий каталог командой pwd.<\\/p><p>- Перед удалением группы файлов проверить их имена с помощью ls.<\\/p><p>- Перед использованием rm -rf всегда несколько раз проверить путь и содержимое каталога<\\/p>\",\"tests\":[{\"question\":\"Какую задачу выполняет команда rm?\",\"answers\":[\"Копирует файлы\",\"Переименовывает каталог\",\"Показывает содержимое файла\",\"Удаляет файлы и каталоги\"],\"correct\":3},{\"question\":\"Какой параметр используется для рекурсивного удаления каталога?\",\"answers\":[\"-a\",\"-r\",\"-l\",\"-h\"],\"correct\":1},{\"question\":\"Какая команда удалит docs вместе с его содержимым?\",\"answers\":[\"rm docs\",\"rm -r docs\",\"rm -a docs\",\"rm -all docs\"],\"correct\":1},{\"question\":\"Что означает рекурсивное удаление?\",\"answers\":[\"Удаление только самого каталога без файлов\",\"Удаление каталога и находящегося внутри него содержимого\",\"Удаление только скрытых файлов\",\"Удаление файла после его копирования\"],\"correct\":1}],\"tasks\":[{\"task\":\"Создайте файл test.txt в каталоге lesson15 и удалите его с помощью rm.\"},{\"task\":\"Создайте два файла one.txt и two.txt, затем удалите их одной командой rm\"},{\"task\":\"Создайте каталог backup с двумя файлами внутри. Удалите каталог backup вместе с его содержимым рекурсивно\"},{\"task\":\"Создайте каталоги project, project\\/docs и project\\/tmp, создайте в каждом каталоге по одному текстовому файлу. Удалите только project\\/tmp вместе с содержимым, сохранив остальные данные\"}]}', 1),
(20, 'Перенаправление потоков', 'redirecting-streams', 16, '{\"theory\":\"<p>В Linux команда обычно получает данные через стандартный ввод и отправляет результат в стандартный вывод. Стандартным вводом и выводом является окно терминала (окно командной строки)<\\/p><p>Перенаправление позволяет изменить источник ввода или место, куда попадёт вывод.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды<\\/strong><\\/p><p>Выполните в GitHub Codespaces:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p linux16\\r\\ncd linux16\\r\\necho \\\"Linux terminal\\\" &gt; info.txt\\r\\necho \\\"GitHub Codespaces\\\" &gt;&gt; info.txt\\r\\necho \\\"Bash shell\\\" &gt;&gt; info.txt<\\/code><\\/pre><p>Теперь файл info.txt содержит три строки:<\\/p><p><code>Linux terminal<\\/code><\\/p><p><code>GitHub Codespaces<\\/code><\\/p><p><code>Bash shell<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Стандартный ввод и стандартный вывод<\\/strong><\\/p><p>У программы обычно есть три стандартных потока.<\\/p><p>Стандартный ввод (stdin) — источник данных для программы. Обычно это клавиатура.<\\/p><p>Стандартный вывод (stdout) — место, куда программа выводит результат. Обычно это терминал.<\\/p><p>Стандартный поток ошибок (stderr) — сообщения об ошибках. В этой лекции подробно его не рассматриваем.<\\/p><p>&nbsp;<\\/p><p>Например:<\\/p><p><code>echo \\\"Hello\\\"<\\/code><\\/p><p>Результат:<\\/p><p><code>Hello<\\/code><\\/p><p>Здесь echo получает текст из командной строки и отправляет его в стандартный вывод, то есть на экран.<\\/p><p>Перенаправление позволяет вместо терминала отправить вывод в файл.<\\/p><p>&nbsp;<\\/p><p><strong>Команда echo<\\/strong><\\/p><p>echo выводит указанный текст.<\\/p><p>Синтаксис:<\\/p><p><code>echo \\\"текст\\\"<\\/code><\\/p><p>На практике echo часто используют для создания небольших файлов, добавления строк в файлы и проверки работы перенаправления.<\\/p><p>&nbsp;<\\/p><p>Пример:<\\/p><p><code>echo \\\"Hello Linux\\\"<\\/code><\\/p><p>Результат:<\\/p><p><code>Hello Linux<\\/code><\\/p><p>&nbsp;<\\/p><p>Пример записи в файл:<\\/p><p><code>echo \\\"Hello Linux\\\" &gt; hello.txt<\\/code><\\/p><p>Команда ничего не выводит на экран. Она создаёт hello.txt и записывает в него:<\\/p><p><code>Hello Linux<\\/code><\\/p><p>Проверить содержимое можно уже изученной командой:<\\/p><p><code>cat hello.txt<\\/code><\\/p><p>Результат:<\\/p><p><code>Hello Linux<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Оператор &gt;<\\/strong><\\/p><p>Символ <code>&gt;<\\/code> перенаправляет стандартный вывод команды в файл.<\\/p><p>Например:<\\/p><p><code>echo \\\"first line\\\" &gt; result.txt<\\/code><\\/p><p>Теперь вывод echo записан не в терминал, а в result.txt.<\\/p><p>Если файл уже существует, &gt; перезаписывает его содержимое.<\\/p><p>Например:<\\/p><p><code>echo \\\"second line\\\" &gt; result.txt<\\/code><\\/p><p><code>cat result.txt<\\/code><\\/p><p>Результат:<\\/p><p><code>second line<\\/code><\\/p><p>Предыдущая строка исчезла.<\\/p><p>&nbsp;<\\/p><p>Это важно: <code>&gt;<\\/code> означает «создать файл или заменить его содержимое».<\\/p><p>&nbsp;<\\/p><p><strong>Оператор &gt;&gt;<\\/strong><\\/p><p>Оператор <code>&gt;&gt;<\\/code> тоже перенаправляет вывод в файл, но добавляет его в конец, не удаляя существующие данные.<\\/p><p>Например:<\\/p><pre><code class=\\\"language-plaintext\\\">echo \\\"first line\\\" &gt; result.txt\\r\\necho \\\"second line\\\" &gt;&gt; result.txt\\r\\ncat result.txt<\\/code><\\/pre><p>Результат:<\\/p><p><code>first line<\\/code><\\/p><p><code>second line<\\/code><\\/p><p>Такой способ часто используется, когда нужно постепенно добавлять информацию в файл.<\\/p><p>Например:<\\/p><p><code>echo \\\"2026-07-29: backup started\\\" &gt;&gt; log.txt<\\/code><\\/p><p><code>echo \\\"2026-07-29: backup finished\\\" &gt;&gt; log.txt<\\/code><\\/p><p><code>cat log.txt<\\/code><\\/p><p>Результат:<\\/p><p><code>2026-07-29: backup started<\\/code><\\/p><p><code>2026-07-29: backup finished<\\/code><\\/p><p>&nbsp;<\\/p><p>Главное различие:<\\/p><p><code>&gt;<\\/code>&nbsp;&nbsp; заменить содержимое файла<\\/p><p><code>&gt;&gt;<\\/code>&nbsp; добавить в конец файла<\\/p><p>&nbsp;<\\/p><p><strong>Оператор &lt;<\\/strong><\\/p><p>Оператор <code>&lt;<\\/code> перенаправляет стандартный ввод.<\\/p><p>То есть программа получает данные не с клавиатуры, а из файла.<\\/p><p>Например:<\\/p><p><code>cat &lt; info.txt<\\/code><\\/p><p>Результат:<\\/p><p><code>Linux terminal<\\/code><\\/p><p><code>GitHub Codespaces<\\/code><\\/p><p><code>Bash shell<\\/code><\\/p><p>Здесь cat получает содержимое info.txt через стандартный ввод.<\\/p><p>Для cat такой пример практически не нужен, потому что проще написать:<\\/p><p><code>cat info.txt<\\/code><\\/p><p>Но сама конструкция <code>&lt;<\\/code> важна для понимания работы потоков и используется с другими командами.<\\/p><p>На данном уровне мы не сможем понять практическую ценность команды <code>&lt;<\\/code>, поэтому, пока, просто запомните её.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Использовать &gt; без проверки, когда файл содержит важные данные: существующее содержимое будет потеряно.<\\/p><p>- Путать &gt; и &gt;&gt;: это может привести к случайной перезаписи файла.<\\/p><p>- Использовать echo для записи больших текстовых файлов: для этого существуют более подходящие инструменты.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- После важных операций проверяйте файл с помощью cat или less.<\\/p><p>- Помните направление: &gt; отправляет вывод в файл, &lt; подаёт данные из файла в команду.<\\/p><p>- Перед использованием &gt; убедитесь, что перезапись файла действительно нужна.<\\/p>\",\"tests\":[{\"question\":\"Как записать вывод команды в файл с заменой его содержимого?\",\"answers\":[\">>\",\"<\",\">\",\"echo\"],\"correct\":3},{\"question\":\"Какой оператор добавляет вывод в конец существующего файла?\",\"answers\":[\"<\",\">\",\">>\",\"echo\"],\"correct\":2},{\"question\":\"Что произойдёт после выполнения команды echo \\\"Hello\\\" > test.txt ?\",\"answers\":[\"Текст появится только на экране\",\"Файл test.txt будет удалён\",\"Текст будет записан в test.txt\",\"Текст будет добавлен только при существовании файла\"],\"correct\":2},{\"question\":\"Что произойдёт после выполнения echo \\\"B\\\" >> data.txt ?\",\"answers\":[\"Содержимое data.txt будет заменено\",\"\\\"B\\\" будет добавлено в конец файла\",\"Файл будет прочитан через стандартный ввод\",\"Команда выведет ошибку\"],\"correct\":1}],\"tasks\":[{\"task\":\"Создайте файл course.txt с помощью echo и >, затем добавьте в его конец две дополнительные строки с помощью >>.\"},{\"task\":\"Создайте файл commands.txt. Последовательно добавьте в него названия изученных вами в этом курсе команд терминала Linux. Используйте только echo и >>. В конце проверьте содержимое файла\"}]}', 1),
(21, 'Конвейеры', 'conveyors', 17, '{\"theory\":\"<p><strong>Подготовка среды<\\/strong><\\/p><p>В этой лекции будут использоваться несколько текстовых файлов и команда curl. Выполните подготовку среды одной командной последовательностью:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p ~\\/pipeline-demo\\r\\ncd ~\\/pipeline-demo\\r\\necho \\\"Linux terminal course\\\" &gt; linux.txt\\r\\necho \\\"GitHub Codespaces training\\\" &gt; github.txt\\r\\necho \\\"Bash command line\\\" &gt; bash.txt<\\/code><\\/pre><p>Проверьте созданные файлы:<\\/p><p><code>ls<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>bash.txt&nbsp; github.txt&nbsp; linux.txt&nbsp; ports.txt<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Конвейеры<\\/strong><\\/p><p>Конвейер соединяет несколько команд.<\\/p><p>Символ &nbsp;<code>|<\\/code> &nbsp;передаёт вывод одной команды на вход следующей.<\\/p><p>Общий вид:<\\/p><p><code>команда1 | команда2<\\/code><\\/p><p>Команды можно соединять в более длинную цепочку:<\\/p><p><code>команда1 | команда2 | команда3<\\/code><\\/p><p>или:<\\/p><p><code>команда1 | команда2 | команда3 | команда4<\\/code><\\/p><p>Данные при этом движутся слева направо:<\\/p><p>команда1 → команда2 → команда3 → команда4<\\/p><p>Каждая следующая команда получает результат предыдущей и выполняет свою задачу.<\\/p><p>&nbsp;<\\/p><p>По другому говоря: конструкция &nbsp;<code>|<\\/code> &nbsp;соединяет команды и передаёт стандартный вывод команды слева на стандартный ввод команды справа.<\\/p><p>&nbsp;<\\/p><p>У конструкции &nbsp;<code>|<\\/code> &nbsp;нет параметров.<\\/p><p>Это оператор командной оболочки Bash.<\\/p><p>&nbsp;<\\/p><p><strong>Когда используется на практике ?<\\/strong><\\/p><p>Конвейеры используют, когда результат одной команды нужно обработать другой командой.<\\/p><p>Типичные ситуации:<\\/p><p>- Получить большой объём данных и оставить только начало.<\\/p><p>- Получить содержимое нескольких файлов и сохранить только нужную часть.<\\/p><p>- Получить HTTP-ответ и сразу передать его другой команде для обработки.<\\/p><p>- Построить последовательность небольших команд, каждая из которых выполняет отдельную задачу.<\\/p><p>&nbsp;<\\/p><p>Пример 1. Просмотр начала HTTP-ответа<\\/p><p>Команда curl может получить большой объём данных.<\\/p><p>Если нужно быстро посмотреть только начало ответа, его можно передать команде head:<\\/p><p><code>curl https:\\/\\/www.gnu.org | head<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><pre><code class=\\\"language-plaintext\\\">&lt;html xmlns=\\\"http:\\/\\/www.w3.org\\/1999\\/xhtml\\\" xml:lang=\\\"en\\\" lang=\\\"en\\\"&gt;\\r\\n&lt;head&gt;\\r\\n&lt;meta http-equiv=\\\"content-type\\\" content=\\\"text\\/html; charset=utf-8\\\" \\/&gt;\\r\\n&lt;link rel=\\\"author\\\" href=\\\"mailto:webmasters@gnu.org\\\" \\/&gt;\\r\\n...<\\/code><\\/pre><p>Здесь:<\\/p><p><code>curl https:\\/\\/www.gnu.org<\\/code><\\/p><p>получает содержимое веб-страницы.<\\/p><p><code>|<\\/code><\\/p><p>передаёт полученные данные следующей команде.<\\/p><p><code>head<\\/code><\\/p><p>показывает только первые строки.<\\/p><p>Это практический пример: вместо просмотра всего ответа можно сразу ограничить объём результата.<\\/p><p>&nbsp;<\\/p><p>Пример 2. Получение HTTP-заголовков и ограничение вывода<\\/p><p>Для быстрой проверки ответа веб-сервера можно получить HTTP-заголовки:<\\/p><p><code>curl -I https:\\/\\/www.gnu.org | head -n4<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>HTTP\\/1.1 200 OK<\\/code><\\/p><p><code>Date: Thu, 03 Sep 2026 09:20:30 GMT<\\/code><\\/p><p><code>Server: Apache<\\/code><\\/p><p><code>Content-Location: home.html<\\/code><\\/p><p><code>curl -I<\\/code> получает заголовки ответа.<\\/p><p><code>head<\\/code> оставляет только первые 4 строки результата.<\\/p><p>Такой подход удобен, когда результат команды большой, а сейчас нужна только его часть.<\\/p><p>&nbsp;<\\/p><p>Пример 3. Объединение содержимого файлов и сохранение результата<\\/p><p>Команда cat может прочитать несколько файлов подряд.&nbsp;<\\/p><p>Полученный результат можно передать head, а затем сохранить в новый файл:<\\/p><p><code>cat linux.txt github.txt bash.txt | head &gt; course-preview.txt<\\/code><\\/p><p>Здесь:<\\/p><p><code>cat linux.txt github.txt bash.txt<\\/code><\\/p><p>объединяет содержимое трёх файлов в один поток данных.<\\/p><p><code>|<\\/code><\\/p><p>передаёт эти данные команде head.<\\/p><p><code>head<\\/code><\\/p><p>оставляет первые строки.<\\/p><p><code>&gt;<\\/code>&nbsp;<\\/p><p>сохраняет полученный результат в файл course-preview.txt.<\\/p><p>Проверим результат:<\\/p><p><code>cat course-preview.txt<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>Linux terminal course<\\/code><\\/p><p><code>GitHub Codespaces training<\\/code><\\/p><p><code>Bash command line<\\/code><\\/p><p>Практическое применение такого подхода — быстро создать сокращённый файл для предварительного просмотра содержимого нескольких файлов.<\\/p><p>&nbsp;<\\/p><p>Конвейер может состоять из нескольких команд:<\\/p><p><code>cat linux.txt github.txt bash.txt | head | tail<\\/code><\\/p><p>(Хотя данный пример не имеет практического смысла. Позднее мы узнаем больше разных полезных команд и увидим, как строить конвейеры из 3 или даже 4 команд)<\\/p><p>&nbsp;<\\/p><p>Важно: длинный конвейер нужно использовать только тогда, когда каждая команда действительно выполняет полезную работу.<\\/p><p>&nbsp;<\\/p><p>Пример 5. Показывает сетевые сокеты компьютера, прежде всего службы, которые ожидают входящие подключения<strong> <\\/strong>и ограничивает вывод результата.<\\/p><p><code>ss -tuln | head<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Конвейер и перенаправление<\\/strong><\\/p><p>Конвейер &nbsp;<code>|<\\/code> &nbsp;и перенаправление <code>&gt;<\\/code> выполняют разные задачи.<\\/p><p>Конвейер:<\\/p><p><code>curl https:\\/\\/www.gnu.org | head<\\/code><\\/p><p>передаёт результат одной команды другой команде.<\\/p><p>Перенаправление:<\\/p><p><code>curl https:\\/\\/www.gnu.org &gt; page.html<\\/code><\\/p><p>сохраняет результат в файл.<\\/p><p>&nbsp;<\\/p><p>Их можно использовать вместе:<\\/p><p><code>curl https:\\/\\/www.gnu.org | head &gt; preview.txt<\\/code><\\/p><p>Здесь:<\\/p><p><code>curl<\\/code><\\/p><p>получает данные.<\\/p><p><code>|<\\/code><\\/p><p>передаёт их команде head.<\\/p><p><code>head<\\/code><\\/p><p>оставляет начало результата.<\\/p><p><code>&gt;<\\/code>&nbsp;<\\/p><p>сохраняет этот результат в файл.<\\/p><p>Проверка:<\\/p><p><code>cat preview.txt<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>&lt;!DOCTYPE html&gt;<\\/code><\\/p><p><code>&lt;html xmlns=\\\"http:\\/\\/www.w3.org\\/1999\\/xhtml\\\" xml:lang=\\\"en\\\" lang=\\\"en\\\"&gt;<\\/code><\\/p><p><code>&lt;head&gt;<\\/code><\\/p><p><code>&lt;meta http-equiv=\\\"content-type\\\" content=\\\"text\\/html; charset=utf-8\\\" \\/&gt;<\\/code><\\/p><p><code>&lt;link rel=\\\"author\\\" href=\\\"mailto:webmasters@gnu.org\\\" \\/&gt;<\\/code><\\/p><p><code>...<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Почему конвейеры важны<\\/strong><\\/p><p>Linux-команды обычно выполняют небольшие отдельные задачи.<\\/p><p>Конвейер позволяет объединять такие команды в последовательность.<\\/p><p>Одна команда получает данные.<\\/p><p>Следующая ограничивает или изменяет результат.<\\/p><p>Ещё одна команда выполняет дальнейшую обработку.<\\/p><p>В конце результат можно вывести на экран или сохранить в файл.<\\/p><p>После изучения следующих тем конвейеры станут ещё полезнее.<\\/p><p>Команды grep, sort, uniq, wc, cut и tr часто используются именно вместе с |.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Не добавляйте команды в конвейер, если они не выполняют полезной работы.<\\/p><p>- Не используйте длинные цепочки без необходимости.<\\/p><p>- Не передавайте большой объём данных через less, если задача состоит в автоматической обработке результата.<\\/p><p>- Не путайте | с &gt;: конвейер передаёт данные команде, а перенаправление записывает их в файл.<\\/p><p>- Не создавайте промежуточные файлы, если результат можно сразу передать следующей команде через конвейер.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Сначала определяйте, что должна делать каждая команда в цепочке.<\\/p><p>- Читайте конвейер слева направо.<\\/p><p>- Проверяйте отдельные команды, прежде чем объединять их в длинный конвейер.<\\/p><p>- Используйте конвейеры для последовательной обработки данных без промежуточных файлов.<\\/p><p>- Используйте &gt; в конце конвейера, если окончательный результат нужно сохранить.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Тестовые вопросы<\\/strong><\\/p><p>&nbsp;<\\/p><p>Что происходит с выводом команды слева от |?<\\/p><p>Он сохраняется в файл указанный справа<\\/p><p>Он удаляется<\\/p><p>Он выводится на экран в окно терминала<\\/p><p>Он становится вводом команды справа ✓<\\/p><p>&nbsp;<\\/p><p>Как правильно записать конвейер из трёх команд?<\\/p><p>команда1 &gt; команда2 &gt; команда3<\\/p><p>команда1 | команда2 | команда3 ✓<\\/p><p>команда1 &lt; команда2 &lt; команда3<\\/p><p>команда1 -&gt; команда2 -&gt; команда3<\\/p><p>&nbsp;<\\/p><p>Что делает команда?<\\/p><p>curl https:\\/\\/example.com | head<\\/p><p>Получает содержимое страницы и показывает его начало ✓<\\/p><p>Получает содержимое страницы и удаляет первые строки страницы<\\/p><p>Сохраняет первые строки страницы в домашний каталог<\\/p><p>Создаёт новую веб-страницу с заголовком<\\/p><p>&nbsp;<\\/p><p>Что делает &gt; в конструкции?<\\/p><p>curl https:\\/\\/example.com | head &gt; preview.txt<\\/p><p>Передаёт данные из файла preview.txt от curl к head<\\/p><p>Записывает результат head в файл preview.txt ✓<\\/p><p>Удаляет файл preview.txt с сайта example.com<\\/p><p>Передаёт содержимое файла preview.txt команде curl<\\/p><p>&nbsp;<\\/p><p>В каком направлении данные проходят через конвейер?<\\/p><p>Справа налево<\\/p><p>Слева направо ✓<\\/p><p>Сверху вниз<\\/p><p>Снизу вверх<\\/p><p>&nbsp;<\\/p><p>Что делает команда?<\\/p><p>cat linux.txt github.txt bash.txt | head<\\/p><p>Создаёт три новых файла в каталоге head<\\/p><p>Удаляет первые строки всех файлов<\\/p><p>Перемещает файлы в каталог head<\\/p><p>Объединяет содержимое файлов и передаёт результат head ✓<\\/p><p>&nbsp;<\\/p><p>Можно ли использовать | вместе с &gt;?<\\/p><p>Нет, эти конструкции несовместимы<\\/p><p>Да, результат конвейера можно сохранить в файл ✓<\\/p><p>Только при использовании команды rm<\\/p><p>Только для каталогов, но не для файлов<\\/p>\",\"tests\":[{\"question\":\"Что происходит с выводом команды слева от |?\",\"answers\":[\"Он сохраняется в файл указанный справа\",\"Он удаляется\",\"Он выводится на экран в окно терминала\",\"Он становится вводом команды справа\"],\"correct\":3},{\"question\":\"Как правильно записать конвейер из трёх команд?\",\"answers\":[\"команда1 > команда2 > команда3\",\"команда1 | команда2 | команда3\",\"команда1 < команда2 < команда3\",\"команда1 -> команда2 -> команда3\"],\"correct\":1},{\"question\":\"Что делает команда?\",\"answers\":[\"curl https:\\/\\/example.com | head\",\"Получает содержимое страницы и показывает его начало\",\"Получает содержимое страницы и удаляет первые строки страницы\",\"Сохраняет первые строки страницы в домашний каталог\"],\"correct\":1},{\"question\":\"Что делает > в конструкции?\",\"answers\":[\"curl https:\\/\\/example.com | head > preview.txt\",\"Передаёт данные из файла preview.txt от curl к head\",\"Записывает результат head в файл preview.txt\",\"Удаляет файл preview.txt с сайта example.com\"],\"correct\":2},{\"question\":\"В каком направлении данные проходят через конвейер?\",\"answers\":[\"Справа налево\",\"Слева направо\",\"Сверху вниз\",\"Снизу вверх\"],\"correct\":1},{\"question\":\"Что делает команда?\",\"answers\":[\"cat linux.txt github.txt bash.txt | head\",\"Создаёт три новых файла в каталоге head\",\"Удаляет первые строки всех файлов\",\"Перемещает файлы в каталог head\"],\"correct\":0},{\"question\":\"Можно ли использовать | вместе с >?\",\"answers\":[\"Нет, эти конструкции несовместимы\",\"Да, результат конвейера можно сохранить в файл\",\"Только при использовании команды rm\",\"Только для каталогов, но не для файлов\"],\"correct\":1}],\"tasks\":[{\"task\":\"Передайте результат команды pwd через конвейер в файл my_work_dir.txt\"},{\"task\":\"Получите HTTP-заголовки сайта https:\\/\\/example.com и передайте результат через конвейер команде head, чтобы посмотреть только начало ответа.\"},{\"task\":\"В рабочем каталоге создайте новый каталог. В каталоге создайте два текстовых файла. В каждый файл добавьте несколько строк текста. Используя cat, объедините содержимое двух учебных файлов, затем передайте результат команде head и сохраните полученный результат в новый файл.\"},{\"task\":\"С любого сайта, на ваше усмотрение, получите HTTP-ответ с помощью curl, передайте его через head, затем через less, результат сохраните в файл. После этого проверьте содержимое файла\"}]}', 1),
(22, 'Поиск текста', 'find', 18, '{\"theory\":\"<p>Для этой лекции подготовим файлы с данными, в которых будем искать нужные строки.&nbsp;<\\/p><p>Выполните весь блок команд целиком:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p ~\\/grep-practice &amp;&amp; cd ~\\/grep-practice\\r\\nprintf \'2026-09-03 INFO Application started\\\\n2026-09-03 INFO Database connected\\\\n2026-09-03 ERROR Database connection failed\\\\n2026-09-03 INFO Request processed\\\\n2026-09-03 WARNING Disk space is low\\\\n2026-09-03 ERROR Request failed\\\\n\' &gt; application.log\\r\\nprintf \'Alice\\\\nBob\\\\nCharlie\\\\nalice\\\\nAdministrator\\\\n\' &gt; users.txt\\r\\nprintf \'server=production\\\\nport=8080\\\\ndebug=false\\\\n\' &gt; config.txt<\\/code><\\/pre><p>Эти команды создадут каталог grep-practice в домашнем каталоге и несколько учебных файлов.&nbsp;<\\/p><p>Пока не обязательно понимать смысл каждой подготовительной команды.<\\/p><p>В этой лекции мы будем использовать созданные файлы для поиска текста.<\\/p><p>&nbsp;<\\/p><p><strong>Команда grep<\\/strong><\\/p><p>Команда grep ищет строки, содержащие указанный текст или шаблон.<\\/p><p>Например, в логах приложения часто нужно найти только сообщения об ошибках.<\\/p><p>В конфигурационном файле — строку с определённым параметром. В списке пользователей — нужное имя.<\\/p><p>Команда grep выводит не отдельное слово, а всю строку, в которой найдено совпадение.<\\/p><p>&nbsp;<\\/p><p>Синтаксис<\\/p><p><code>grep \\\"текст\\\" файл<\\/code><\\/p><p>Сначала указывается искомый текст, затем файл, в котором выполняется поиск.<\\/p><p>Наиболее важные параметры<\\/p><p><code>-i<\\/code> — искать без учёта регистра.<\\/p><p><code>-v<\\/code> — выводить строки, которые не содержат указанный текст.<\\/p><p><code>-n<\\/code> — показывать номера строк с найденными совпадениями.<\\/p><p><code>-r<\\/code> — искать рекурсивно в каталоге и его подкаталогах.<\\/p><p>Эти параметры можно использовать вместе.<\\/p><p>&nbsp;<\\/p><p>Пример 1. Поиск ошибок в журнале приложения<\\/p><p>В файле application.log найдём все строки с сообщениями об ошибках:<\\/p><pre><code class=\\\"language-plaintext\\\">grep \\\"ERROR\\\" application.log<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>2026-09-03 ERROR Database connection failed<\\/code><\\/p><p><code>2026-09-03 ERROR Request failed<\\/code><\\/p><p>Команда просмотрела файл и вывела только строки, содержащие ERROR.<\\/p><p>На практике это один из самых распространённых способов использования grep: поиск ошибок в логах.<\\/p><p>&nbsp;<\\/p><p>Пример 2. Поиск без учёта регистра<\\/p><p>В списке пользователей найдём имя alice независимо от регистра:<\\/p><pre><code class=\\\"language-plaintext\\\">grep -i \\\"alice\\\" users.txt<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>Alice<\\/code><\\/p><p><code>alice<\\/code><\\/p><p>Без параметра <code>-i<\\/code> команда учитывает регистр символов.<\\/p><p>То есть Alice и alice для неё являются разным текстом.<\\/p><p>&nbsp;<\\/p><p>Пример 3. Поиск с номерами строк<\\/p><p>При работе с конфигурационными или программными файлами полезно знать номер найденной строки.<\\/p><p>Найдём все строки с ошибками и покажем их номера:<\\/p><pre><code class=\\\"language-plaintext\\\">grep -n \\\"ERROR\\\" application.log<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>3:2026-09-03 ERROR Database connection failed<\\/code><\\/p><p><code>6:2026-09-03 ERROR Request failed<\\/code><\\/p><p>Число перед двоеточием — номер строки в файле.<\\/p><p>&nbsp;<\\/p><p>Пример 4. Исключение строк<\\/p><p>Параметр <code>-v<\\/code> меняет логику поиска.<\\/p><p>Команда выводит строки, которые не содержат указанный текст.<\\/p><p>Выведем из журнала все сообщения, кроме ошибок:<\\/p><pre><code class=\\\"language-plaintext\\\">grep -v \\\"ERROR\\\" application.log<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>2026-09-03 INFO Application started<\\/code><\\/p><p><code>2026-09-03 INFO Database connected<\\/code><\\/p><p><code>2026-09-03 INFO Request processed<\\/code><\\/p><p><code>2026-09-03 WARNING Disk space is low<\\/code><\\/p><p>Это полезно, когда нужно убрать определённый тип строк из вывода.<\\/p><p>&nbsp;<\\/p><p>Пример 5. Поиск во всех файлах каталога<\\/p><p>Параметр -r позволяет искать текст рекурсивно: в указанном каталоге и всех его подкаталогах.<\\/p><p>Найдём все файлы текущего каталога, содержащие текст production:<\\/p><pre><code class=\\\"language-plaintext\\\">grep -r \\\"production\\\" .<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.\\/config.txt:server=production<\\/code><\\/p><p>Точка <code>.<\\/code> означает текущий каталог.<\\/p><p>На практике рекурсивный поиск часто используется в каталогах с конфигурационными файлами, исходным кодом или логами.<\\/p><p>&nbsp;<\\/p><p><strong>grep и конвейеры<\\/strong><\\/p><p>В предыдущей лекции вы изучили конвейер &nbsp;<code>|<\\/code> .<\\/p><p>grep часто используется вместе с ним.<\\/p><p>Например, history выводит историю выполненных команд.<\\/p><p>Можно найти среди неё команды, содержащие grep:<\\/p><pre><code class=\\\"language-plaintext\\\">history | grep \\\"grep\\\"<\\/code><\\/pre><p>Ожидаемый вывод зависит от истории команд:<\\/p><p><code>...<\\/code><\\/p><p>Здесь вывод history передаётся команде grep, которая оставляет только строки с текстом grep.<\\/p><p>&nbsp;<\\/p><p>Это один из самых важных способов практического использования команды:&nbsp;<br>одна команда получает большой объём данных, а grep оставляет только нужную информацию.<\\/p><p>&nbsp;<\\/p><p><strong>Поиск точного текста<\\/strong><\\/p><p>По умолчанию grep ищет указанную последовательность символов внутри строки.<\\/p><p>Например:<\\/p><p><code>grep \\\"Alice\\\" users.txt<\\/code><\\/p><p>Ожидаемый вывод:<\\/p><p><code>Alice<\\/code><\\/p><p>Если в файле была бы строка AliceAdmin, она тоже могла бы попасть в результаты, потому что содержит текст Alice.<\\/p><p>В дальнейшем курсе вы узнаете другие инструменты обработки текста.&nbsp;<\\/p><p>Сейчас главное запомнить основное назначение grep: поиск нужных строк в файлах и выводе других команд.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Искать ошибки только визуально в больших логах, когда можно использовать grep.<\\/p><p>- Забывать про регистр символов: при необходимости использовать -i.<\\/p><p>- Использовать grep -r в больших каталогах без необходимости.<\\/p><p>- Считать отсутствие вывода ошибкой: это может означать, что совпадений просто нет.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Сначала переходите в нужный каталог, чтобы не указывать длинные пути к файлам.<\\/p><p>- Для поиска в логах используйте точные и понятные слова, например ERROR.<\\/p><p>- При поиске без учёта регистра используйте -i.<\\/p><p>- Добавляйте -n, когда важно найти номер строки.<\\/p><p>- Используйте grep в конвейере для фильтрации большого вывода других команд.<\\/p>\",\"tests\":[{\"question\":\"Что делает команда grep?\",\"answers\":[\"Удаляет строки из файла\",\"Ищет текст и выводит подходящие строки\",\"Создаёт новый текстовый файл\",\"Изменяет права доступа к файлу\"],\"correct\":1},{\"question\":\"Какой синтаксис правильно выполняет поиск текста в файле?\",\"answers\":[\"grep файл \\\"текст\\\"\",\"grep \\\"текст\\\" файл\",\"grep файл текст\",\"grep \\\"текст\\\" > файл\"],\"correct\":1},{\"question\":\"Что будет искать команда:    grep \\\"ERROR\\\" application.log   ?\",\"answers\":[\"Все файлы с именем application.log\",\"Строки, не содержащие ERROR\",\"Только строки, содержащие application\",\"Только строки, содержащие ERROR\"],\"correct\":3},{\"question\":\"Какой параметр позволяет игнорировать регистр символов?\",\"answers\":[\"-r\",\"-n\",\"-v\",\"-i\"],\"correct\":3},{\"question\":\"Что выведет команда:    grep -i \\\"alice\\\" users.txt    ?\",\"answers\":[\"Только alice в нижнем регистре\",\"Строки, содержащие alice, независимо от регистра\",\"Только строки, полностью совпадающие с именем файла\",\"Номера строк, где найдено слово\"],\"correct\":1},{\"question\":\"Для чего используется параметр -n?\",\"answers\":[\"Для поиска файлов по имени\",\"Для вывода количества найденных строк\",\"Для вывода номеров строк с совпадениями\",\"Для игнорирования регистра\"],\"correct\":2},{\"question\":\"Что делает параметр -v?\",\"answers\":[\"Выводит строки, не содержащие указанный текст\",\"Показывает номер версии команды grep\",\"Ищет текст только в подкаталогах\",\"Открывает файл для редактирования\"],\"correct\":0},{\"question\":\"Что означает точка в команде:    grep -r \\\"production\\\" .    ?\",\"answers\":[\"Предыдущий каталог\",\"Домашний каталог пользователя\",\"Текущий каталог\",\"Корневой каталог Linux\"],\"correct\":2},{\"question\":\"Какую конструкцию можно использовать для передачи вывода одной команды в grep?\",\"answers\":[\">\",\"|\",\"<\",\">>\"],\"correct\":1},{\"question\":\"Что обычно означает отсутствие вывода команды grep?\",\"answers\":[\"Команда завершилась с ошибкой\",\"В файле не найдено совпадений\",\"Файл был удалён\",\"grep автоматически изменил файл\"],\"correct\":1}],\"tasks\":[{\"task\":\"В каталоге ~\\/grep-practice создайте файл deploy.log и запишите туда следующий текст:\\r\\n2026-09-03 09:10 INFO Deployment started \\r\\n2026-09-03 09:11 INFO Uploading application files \\r\\n2026-09-03 09:12 INFO Database migration completed \\r\\n2026-09-03 09:13 INFO Deployment completed successfully \\r\\n2026-09-03 10:25 INFO Deployment started \\r\\n2026-09-03 10:26 ERROR Failed to connect to server \\r\\n2026-09-03 10:27 ERROR Deployment aborted \\r\\n2026-09-03 11:40 INFO Deployment started \\r\\n2026-09-03 11:42 INFO Deployment completed successfully\\r\\n(это записи (логи) об этапах развёртывания некоего web-приложения на сервер).\\r\\n(Если вы не помните, как в Linux записать текст в файл - поищите в соответствующей лекции на курсе или спросите в ИИ)\\r\\nВ этом файле: \\r\\n1. Найдите все строки с текстом ERROR.\\r\\n\\r\\n2. Найдите все строки с текстом INFO.\\r\\n\\r\\n3. Найдите все строки с текстом INFO, игнорируя регистр.\\r\\n\\r\\n4. Найдите все строки с текстом INFO и выведите их номера.\\r\\n\\r\\n5. Найдите все строки, кроме содержащих INFO.\"},{\"task\":\"С помощью grep найдите строку с параметром port в файле config.txt.\"},{\"task\":\"Найдите в текущем каталоге и всех его подкаталогах строки, содержащие debug\"},{\"task\":\"Используя конвейер  | , найдите в выводе history все команды, содержащие cd\"}]}', 1);
INSERT INTO `lessons` (`id`, `title_ru`, `slug`, `lesson_order`, `content`, `is_published`) VALUES
(23, 'Поиск файлов', 'find-and-which', 19, '{\"theory\":\"<p>В Linux файлы часто нужно искать не только в текущем каталоге, но и во всей структуре каталогов. Для этого используются разные инструменты.<\\/p><p>&nbsp;<\\/p><p>Команда find ищет файлы и каталоги по заданным условиям: имени, типу и другим признакам.<\\/p><p>Команда which помогает узнать, какой исполняемый файл будет запущен при вводе команды в терминале.<\\/p><p>&nbsp;<\\/p><p><strong>Подготовка среды GitHub Codespaces<\\/strong><\\/p><p>Выполните один раз:<\\/p><pre><code class=\\\"language-plaintext\\\">mkdir -p search-practice\\/projects\\/api\\/logs search-practice\\/projects\\/web\\r\\ntouch search-practice\\/projects\\/api\\/config.json\\r\\ntouch search-practice\\/projects\\/api\\/app.log\\r\\ntouch search-practice\\/projects\\/api\\/logs\\/error.log\\r\\ntouch search-practice\\/projects\\/web\\/config.json\\r\\ntouch search-practice\\/projects\\/web\\/index.html\\r\\ncd search-practice<\\/code><\\/pre><p>Будет создана учебная структура:<\\/p><p><code>search-practice<\\/code><\\/p><p><code>└── projects<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; ├── api<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; │&nbsp;&nbsp; ├── app.log<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; │&nbsp;&nbsp; ├── config.json<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; │&nbsp;&nbsp; └── logs<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; │&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; └── error.log<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp; └── web<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ├── config.json<\\/code><\\/p><p><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; └── index.html<\\/code><\\/p><p>&nbsp;<\\/p><p><strong>Команда find<\\/strong><\\/p><p>find [файнд] - найди<\\/p><p>find ищет файлы и каталоги, начиная с указанного места.<\\/p><p>В отличие от ls, команда find может искать рекурсивно во вложенных каталогах.<\\/p><p>Это особенно полезно в больших проектах, на серверах и при работе с логами.<\\/p><p>Синтаксис<\\/p><p><code>find место_поиска условие<\\/code><\\/p><p>Если на место_поиска указана точка . - это означает текущий каталог.<\\/p><p>Наиболее важные условия (параметры) :<\\/p><p><code>-name<\\/code> — поиск по точному имени или шаблону имени.<\\/p><p><code>find . -name имя<\\/code><\\/p><p><code>-type f<\\/code> — искать только обычные файлы.<\\/p><p><code>find . -type f<\\/code><\\/p><p><code>-type d<\\/code> — искать только каталоги.<\\/p><p><code>find . -type d<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>- Поиск файла конфигурации в проекте.<\\/p><p>- Поиск файлов с определённым расширением.<\\/p><p>- Поиск логов.<\\/p><p>- Поиск каталога в большой структуре проекта.<\\/p><p>- Поиск файла по имени<\\/p><p>&nbsp;<\\/p><p>Найдём все файлы с именем config.json:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -name config.json<\\/code><\\/pre><p>(Точка <code>.<\\/code> означает текущий каталог)<\\/p><p>Ожидаемый вывод:<\\/p><p><code>.\\/projects\\/api\\/config.json<\\/code><\\/p><p><code>.\\/projects\\/web\\/config.json<\\/code><\\/p><p>Команда начинает поиск в текущем каталоге и проверяет все вложенные каталоги.<\\/p><p>Такой поиск полезен, например, когда нужно найти все конфигурационные файлы одного типа.<\\/p><p>&nbsp;<\\/p><p>Поиск по шаблону<\\/p><p>Найдём все файлы с расширением .log:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -name \\\"*.log\\\"<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.\\/projects\\/api\\/app.log<\\/code><\\/p><p><code>.\\/projects\\/api\\/logs\\/error.log<\\/code><\\/p><p>Символ * означает любое количество любых символов.<\\/p><p>Важно заключать шаблон в кавычки. В этом случае find получает шаблон и выполняет поиск самостоятельно.<\\/p><p>&nbsp;<\\/p><p>Поиск только файлов<\\/p><p>Найдём все обычные файлы:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -type f<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.\\/projects\\/api\\/logs\\/error.log<\\/code><\\/p><p><code>.\\/projects\\/api\\/config.json<\\/code><\\/p><p><code>.\\/projects\\/api\\/app.log<\\/code><\\/p><p><code>.\\/projects\\/web\\/config.json<\\/code><\\/p><p><code>.\\/projects\\/web\\/index.html<\\/code><\\/p><p>Параметр -type f полезен, когда результат поиска должен содержать только файлы.<\\/p><p>Например, можно одновременно искать по имени и указывать тип:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -type f -name \\\"*.log\\\"<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.\\/projects\\/api\\/logs\\/error.log<\\/code><\\/p><p><code>.\\/projects\\/api\\/app.log<\\/code><\\/p><p>Это практичный способ поиска логов в структуре проекта.<\\/p><p>&nbsp;<\\/p><p>Поиск только каталогов<\\/p><p>Найдём все каталоги:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -type d<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.<\\/code><\\/p><p><code>.\\/projects<\\/code><\\/p><p><code>.\\/projects\\/api<\\/code><\\/p><p><code>.\\/projects\\/api\\/logs<\\/code><\\/p><p><code>.\\/projects\\/web<\\/code><\\/p><p>Это полезно, когда нужно найти определённый каталог среди большого количества файлов.<\\/p><p>&nbsp;<\\/p><p>Например, найдём каталог logs:<\\/p><pre><code class=\\\"language-plaintext\\\">find . -type d -name logs<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>.\\/projects\\/api\\/logs<\\/code><\\/p><p>&nbsp;<\\/p><p>Поиск во всём домашнем каталоге<\\/p><p>В предыдущих примерах поиск начинался с текущего каталога.<\\/p><p>Можно указать другой каталог.<\\/p><p>Например:<\\/p><pre><code class=\\\"language-plaintext\\\">find ~ -type f -name \\\"*.log\\\"<\\/code><\\/pre><p>Здесь <code>~<\\/code> означает домашний каталог пользователя.<\\/p><p>На практике поиск по домашнему каталогу может занять больше времени и вывести большое количество результатов.<\\/p><p>&nbsp;<\\/p><p><strong>Команда which<\\/strong><\\/p><p>which - который<\\/p><p>Когда вы вводите в терминале название команды, например curl, Linux определяет, какую программу нужно запустить.<\\/p><p>Понятно, что программа должна быть установлена в системе.<\\/p><p>Команда which показывает путь к программе, которая будет запущена.<\\/p><p>По другому говоря - путь к найденному исполняемому файлу.<\\/p><p>Синтаксис<\\/p><p><code>which команда<\\/code><\\/p><p>&nbsp;<\\/p><p>Когда используется на практике ?<\\/p><p>- Проверка, установлена ли программа.<\\/p><p>- Поиск исполняемого файла команды.<\\/p><p>- Проверка, какая версия программы запускается при наличии нескольких копий.<\\/p><p>- Диагностика окружения разработчика или сервера.<\\/p><p>- Поиск расположения команды<\\/p><p>&nbsp;<\\/p><p>Узнаем путь к программе curl:<\\/p><pre><code class=\\\"language-plaintext\\\">which curl<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/usr\\/bin\\/curl<\\/code><\\/p><p>Путь может отличаться в зависимости от Linux-системы.<\\/p><p>Ещё один пример:<\\/p><pre><code class=\\\"language-plaintext\\\">which python<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/home\\/codespace\\/.python\\/current\\/bin\\/python<\\/code><\\/p><p>Или в некоторых средах:<\\/p><p><code>\\/usr\\/bin\\/python3<\\/code><\\/p><p>Если команда найдена, which выводит путь к её исполняемому файлу.<\\/p><p>&nbsp;<\\/p><p>Проверка существования команды<\\/p><p>Можно проверить наличие команды:<\\/p><pre><code class=\\\"language-plaintext\\\">which git<\\/code><\\/pre><p>Ожидаемый вывод:<\\/p><p><code>\\/usr\\/local\\/bin\\/git<\\/code><\\/p><p>Если программа не найдена, which обычно не выводит путь.<\\/p><p>Это может помочь понять, установлена ли нужная программа и доступна ли она для запуска из терминала.<\\/p><p>&nbsp;<\\/p><p><strong>find и which: когда использовать<\\/strong><\\/p><p>find ищет файлы и каталоги в файловой системе.<\\/p><p>which ищет исполняемый файл команды в каталогах, куда устанавливаются программы.<\\/p><p>Например, чтобы найти файл конфигурации:<\\/p><p><code>find . -name config.json<\\/code><\\/p><p>Чтобы узнать расположение программы curl:<\\/p><p><code>which curl<\\/code><\\/p><p>Это разные задачи. which не является заменой find.<\\/p><p>&nbsp;<\\/p><p><strong>Плохие практики<\\/strong><\\/p><p>- Не используйте поиск от &nbsp;\\/ &nbsp;(корневой каталог) без необходимости: это может быть медленно и привести к большому количеству сообщений об ошибках доступа.<\\/p><p>- Не ищите все файлы командой find без условий, если нужен конкретный тип или имя.<\\/p><p>- Не забывайте кавычки вокруг шаблонов, например \\\"*.log\\\".<\\/p><p>- Не используйте which для поиска обычных файлов: он предназначен для поиска исполняемых команд.<\\/p><p>&nbsp;<\\/p><p><strong>Лучшие практики<\\/strong><\\/p><p>- Начинайте поиск find с наиболее подходящего каталога, а не со всей файловой системы.<\\/p><p>- Сочетайте -type и -name, если знаете, что ищете именно файл или каталог.<\\/p><p>- Используйте шаблоны для поиска файлов одного типа, например \\\"*.log\\\".<\\/p><p>- Используйте which, когда нужно понять, какой исполняемый файл запускает команда.<\\/p>\",\"tests\":[{\"question\":\"Какая команда предназначена для рекурсивного поиска файлов и каталогов?\",\"answers\":[\"which\",\"find\",\"ls\",\"grep\"],\"correct\":1},{\"question\":\"Что означает точка . в команде find . -name config.json?\",\"answers\":[\"Домашний каталог\",\"Корневой каталог\",\"Текущий каталог\",\"Каталог конфигурации\"],\"correct\":2},{\"question\":\"Что означает -type f?\",\"answers\":[\"Искать только каталоги\",\"Искать только файлы\",\"Искать файлы с типом f\",\"Искать файлы с расширением f\"],\"correct\":1},{\"question\":\"Какая команда найдёт файлы с расширением .log?\",\"answers\":[\"find . -type \\\"*.log\\\"\",\"which \\\"*.log\\\"\",\"find *.log\",\"find . -name \\\"*.log\\\"\"],\"correct\":3},{\"question\":\"Что означает -type d?\",\"answers\":[\"Искать только каталоги\",\"Искать файлы с расширением .d\",\"Искать удалённые файлы\",\"Искать файлы с типом .d\"],\"correct\":0},{\"question\":\"Для чего используется команда which?\",\"answers\":[\"Для поиска текста внутри файлов\",\"Для поиска расположения исполняемой команды\",\"Для поиска всех файлов в текущем каталоге\",\"Для определения размера файла\"],\"correct\":1},{\"question\":\"Что выводит which curl, если команда найдена?\",\"answers\":[\"Содержимое программы curl\",\"Версию программы\",\"Путь к исполняемому файлу curl\",\"Список всех файлов программы curl\"],\"correct\":2}],\"tasks\":[{\"task\":\"В текущем каталоге найдите все файлы с именем config.json.\"},{\"task\":\"Найдите все каталоги в учебной структуре, начиная поиск из текущего каталога.\"},{\"task\":\"Создайте каталог practice\\/find и внутри него файлы app.log, error.log и config.json. Найдите все файлы с расширением .log.\"},{\"task\":\"Создайте каталог project с подкаталогами backend\\/logs и frontend. \\r\\nВ каждом из каталогов backend и frontend создайте файл config.json. \\r\\nНайдите оба файла одной командой.\"}]}', 1);

